let LANG = (() => {
  try {
    const saved = localStorage.getItem('wc_lang');
    if (LANGS.some((x) => x.code === saved)) return saved;
  } catch (e) { /* fall through to browser-language detection */ }
  // First visit: greet her in her own browser language (pt-BR phone -> pt).
  const nav = String((typeof navigator !== 'undefined' && navigator.language) || '').toLowerCase();
  const hit = LANGS.find((l) => l.code !== 'en' && nav.startsWith(l.code));
  return hit ? hit.code : 'en';
})();

function t(key, vars) {
  let s = (I18N[LANG] && I18N[LANG][key]) || I18N.en[key] || key;
  if (vars) for (const k in vars) s = s.split('{' + k + '}').join(String(vars[k]));
  return s;
}

/* Pre-login entry surfaces that live OUTSIDE the show() view map — the
   static age gate, the welcome splash, and the invite / referral /
   affiliate signup forms — register a re-render hook here so a
   language switch redraws THAT screen in the new language instead of
   dumping the visitor onto the landing view mid-signup. show() clears
   entryRerender (any in-app navigation means the entry form was
   left); routeInitial clears splashLangRefresh (the splash handed off
   to the real destination); checkAgeGate clears its own hook when the
   visitor passes or is denied. */
let entryRerender = null;
let splashLangRefresh = null;
let gateLangRefresh = null;

/* Language picker — ONE compact link. Tapping it opens a sheet with a
   scrollable list of languages; she can scroll and tap, or TYPE to filter. */
function langPillsHTML() {
  const cur = LANGS.find((l) => l.code === LANG) || LANGS[0];
  return `<button type="button" class="lang-link" data-langtoggle>${cur.flag} ${cur.label} <span class="lang-caret">▾</span></button>`;
}
function openLangSheet() {
  let sheet = document.getElementById('langSheet');
  if (!sheet) {
    sheet = document.createElement('div');
    sheet.id = 'langSheet';
    sheet.className = 'lang-sheet';
    document.body.appendChild(sheet);
    sheet.addEventListener('click', (e) => { if (e.target === sheet) closeLangSheet(); });
  }
  sheet.innerHTML = `
    <div class="lang-sheet-card">
      <div class="lang-sheet-title">🌐 ${t('language')}</div>
      <input class="input lang-search" type="text" placeholder="${t('language_search_ph')}" autocomplete="off">
      <div class="lang-list">${LANGS.map((l) =>
        `<button type="button" class="lang-opt${LANG === l.code ? ' on' : ''}" data-setlang="${l.code}"><span>${l.flag} ${l.label}</span>${LANG === l.code ? '<span class="lang-check">✓</span>' : ''}</button>`).join('')}</div>
      <button type="button" class="btn ghost" data-langclose style="width:100%">${t('cancel')}</button>
    </div>`;
  // The age gate and the welcome splash sit at z-index 9999 — while
  // either is up, the sheet must ride above it or the language options
  // hide behind the door.
  sheet.classList.toggle('over-splash', !!splashLangRefresh || !!gateLangRefresh);
  sheet.hidden = false;
  const input = sheet.querySelector('.lang-search');
  input.addEventListener('input', () => {
    const q = input.value.trim().toLowerCase();
    sheet.querySelectorAll('.lang-opt').forEach((b) => {
      b.style.display = b.textContent.toLowerCase().includes(q) ? '' : 'none';
    });
  });
  setTimeout(() => { try { input.focus(); } catch (e) { /* noop */ } }, 60);
}
function closeLangSheet() {
  const sheet = document.getElementById('langSheet');
  if (sheet) sheet.hidden = true;
}
function langCardHTML() {
  return `<div class="card">
      <div style="font-weight:800;margin-bottom:6px">🌐 ${t('language')}</div>
      <div class="muted small" style="margin-bottom:10px">${t('language_note')}</div>
      ${langPillsHTML()}
    </div>`;
}
function applyLang(code) {
  if (!LANGS.some((x) => x.code === code)) return false;
  LANG = code;
  try { localStorage.setItem('wc_lang', code); } catch (e) { /* private mode */ }
  document.documentElement.lang = code === 'pt' ? 'pt-BR' : code === 'zh' ? 'zh-CN' : code;
  return true;
}
/* Account language is the cross-device copy: adopt it when this device has
   no explicit choice; if the device choice differs, push the device's up. */
function syncLangFromUser(u) {
  if (!u || !LANGS.some((x) => x.code === u.language) || u.language === LANG) return;
  let local = null;
  try { local = localStorage.getItem('wc_lang'); } catch (e) { /* ignore */ }
  if (!local) applyLang(u.language);
  else if (S.token) api('/me/language', { method: 'PATCH', body: JSON.stringify({ language: local }) }).catch(() => {});
}
async function setLang(code) {
  if (code === LANG || !applyLang(code)) return;
  if (S.token) api('/me/language', { method: 'PATCH', body: JSON.stringify({ language: code }) }).catch(() => {});
  toast(t('language_set'));
  // At the age gate there is nothing else on screen — just re-label
  // the gate in place; the boot sequence is still waiting on it.
  if (gateLangRefresh) { gateLangRefresh(); return; }
  // On the welcome splash there is no view to re-render yet — just swap
  // the splash's own lines in place (routing happens on Enter).
  if (splashLangRefresh) { splashLangRefresh(); return; }
  // Re-render the current view in place. Never tear down a live stream —
  // its labels pick the new language up on the next navigation.
  if (['liveBroadcast', 'liveWatch'].includes(S.view)) { renderTabbar(); return; }
  // Entry forms (invite / referral / affiliate signup) aren't show()
  // views — redraw the form itself so she keeps her place at the door.
  if (entryRerender) { entryRerender(); return; }
  show(S.view, S.viewParams || {});
}
document.addEventListener('click', (e) => {
  if (e.target.closest('[data-langtoggle]')) { openLangSheet(); return; }
  if (e.target.closest('[data-langclose]')) { closeLangSheet(); return; }
  const b = e.target.closest('[data-setlang]');
  if (b) { closeLangSheet(); setLang(b.dataset.setlang); }
});
document.addEventListener('keydown', (e) => { if (e.key === 'Escape') closeLangSheet(); });
document.documentElement.lang = LANG === 'pt' ? 'pt-BR' : LANG;

/* ---------------- state ---------------- */

const S = {
  token: localStorage.getItem('wc_token') || null,
  guestToken: localStorage.getItem('wc_guest') || null,
  user: null,       // logged-in user (public fields)
  wallet: null,
  model: null,      // model profile if role=model
  ws: null,
  view: 'landing',
  viewParams: {},   // last params passed to show() — lets setLang re-render in place
  conv: null,       // active conversation {id, other, is_paused, free_remaining}
  messages: [],
  call: null,       // active call state
  previewFan: false, // admin-only: browsing the app as a fan, no sign-out needed
  live: null,       // active live session state {sessionId, role, ...}
};

/* ---------------- AI nudity monitor (NSFWJS, client-side) ---------------- */
/* Loads lazily only when a fan opens a live view. If it fails (offline,    */
/* blocked CDN), the app falls back to the model's manual "Go Explicit".   */
const NSFW = {
  model: null,
  loading: false,
  failed: false,
  failCount: 0,
  async ensure() {
    if (this.model) return this.model;
    if (this.loading) return null;
    // Don't permanently give up — retry with backoff (max 5 attempts)
    if (this.failed && this.failCount >= 5) return null;
    this.loading = true;
    try {
      // esm.sh bundles tfjs + deps; jsdelivr's dist is CJS-only and won't load via <script>
      const mod = await import(/* webpackIgnore: true */ 'https://esm.sh/nsfwjs@2.4.2');
      const loadFn = mod.load || (mod.default && mod.default.load);
      this.model = await loadFn();
      this.loading = false;
      this.failed = false;
      this.failCount = 0;
      // Notify any waiting UI that AI is now active
      if (typeof window !== 'undefined') window.dispatchEvent(new CustomEvent('nsfw-ready'));
      return this.model;
    } catch (e) {
      console.warn('NSFWJS failed to load, using manual mode:', e);
      this.failed = true;
      this.failCount++;
      this.loading = false;
      // Auto-retry in 30s (up to 5 attempts)
      if (this.failCount < 5) {
        setTimeout(() => { this.failed = false; this.ensure(); }, 30000);
      }
      return null;
    }
  },
  // Classify a video element via canvas snapshot. Returns true if explicit.
  async isExplicit(videoEl) {
    const model = await this.ensure();
    if (!model || !videoEl || videoEl.readyState < 2 || videoEl.videoWidth === 0) return false;
    try {
      const c = NSFW._canvas || (NSFW._canvas = document.createElement('canvas'));
      c.width = 224; c.height = 224;
      const ctx = c.getContext('2d', { willReadFrequently: true });
      // center-crop to square
      const vw = videoEl.videoWidth, vh = videoEl.videoHeight;
      const s = Math.min(vw, vh), sx = (vw - s) / 2, sy = (vh - s) / 2;
      ctx.drawImage(videoEl, sx, sy, s, s, 0, 0, 224, 224);
      const preds = await model.classify(c);
      for (const p of preds) {
        if ((p.className === 'Porn' || p.className === 'Hentai') && p.probability > 0.7) {
          console.log('[AI monitor] explicit detected:', p.className, p.probability.toFixed(2));
          return true;
        }
      }
      return false;
    } catch (e) {
      console.warn('NSFW classify failed:', e);
      return false;
    }
  },
};

async function api(path, opts) {
  opts = opts || {};
  // Storefront tabs (owner pivot, Oct 18 2026): directory reads carry
  // the active section tab; the server filters by it. Entry always
  // starts on the Female tab (browseTab's initial value) — the tab is
  // per-session state, never stored, never asked.
  if ((!opts.method || opts.method === 'GET') &&
      (path === '/models' || path === '/live' || path === '/live/schedule')) {
    path += '?tab=' + browseTab;
  }
  const headers = Object.assign({ 'Content-Type': 'application/json' }, opts.headers || {});
  if (S.token) headers['Authorization'] = 'Bearer ' + S.token;
  else if (S.guestToken) headers['X-Guest-Token'] = S.guestToken;
  const ctrl = new AbortController();
  const timeout = setTimeout(() => ctrl.abort(), 15000); // 15s timeout
  try {
    const r = await fetch('/api' + path, Object.assign({}, opts, { headers, signal: ctrl.signal }));
    clearTimeout(timeout);
    let data = {};
    try { data = await r.json(); } catch (e) { /* non-JSON */ }
    return { status: r.status, data };
  } catch (e) {
    clearTimeout(timeout);
    return { status: 0, data: { error: 'network_error' } };
  }
}

/* ---------- Photo cropper: square crop before upload (admin + models) ---------- */
function openPhotoCropper(file, onCrop) {
  const url = URL.createObjectURL(file);
  const img = new Image();
  img.onload = () => {
    const overlay = document.createElement('div');
    overlay.id = 'crop-overlay';
    overlay.innerHTML = `
      <div class="crop-box">
        <div class="crop-title">Crop your photo</div>
        <div class="crop-viewport" id="crop-viewport">
          <img id="crop-img" src="${url}" alt="">
          <div class="crop-grid"></div>
        </div>
        <div class="crop-hint">Drag to move · pinch or scroll to zoom</div>
        <div class="crop-actions">
          <button class="btn ghost" id="crop-cancel">Cancel</button>
          <button class="btn" id="crop-save">Crop &amp; Save</button>
        </div>
      </div>`;
    document.body.appendChild(overlay);

    const viewport = overlay.querySelector('#crop-viewport');
    const cimg = overlay.querySelector('#crop-img');
    let scale = 1, ox = 0, oy = 0;
    const minScale = 1;

    // Fit image to cover the square viewport initially
    const vw = viewport.clientWidth;
    const fitScale = Math.max(vw / img.naturalWidth, vw / img.naturalHeight);
    scale = fitScale;
    apply();

    function apply() {
      cimg.style.transform = `translate(-50%, -50%) translate(${ox}px, ${oy}px) scale(${scale})`;
    }
    function clamp() {
      const w = img.naturalWidth * scale, h = img.naturalHeight * scale;
      const maxX = Math.max(0, (w - vw) / 2), maxY = Math.max(0, (h - vw) / 2);
      ox = Math.min(maxX, Math.max(-maxX, ox));
      oy = Math.min(maxY, Math.max(-maxY, oy));
    }

    // Drag to pan
    let dragging = false, sx = 0, sy = 0;
    cimg.addEventListener('pointerdown', (e) => {
      dragging = true; sx = e.clientX - ox; sy = e.clientY - oy;
      cimg.setPointerCapture(e.pointerId);
    });
    cimg.addEventListener('pointermove', (e) => {
      if (!dragging) return;
      ox = e.clientX - sx; oy = e.clientY - sy;
      clamp(); apply();
    });
    cimg.addEventListener('pointerup', () => { dragging = false; });
    cimg.addEventListener('pointercancel', () => { dragging = false; });

    // Pinch to zoom
    let pinchDist = 0;
    viewport.addEventListener('touchmove', (e) => {
      if (e.touches.length === 2) {
        e.preventDefault();
        const d = Math.hypot(e.touches[0].clientX - e.touches[1].clientX,
                              e.touches[0].clientY - e.touches[1].clientY);
        if (pinchDist) {
          scale = Math.max(fitScale, Math.min(fitScale * 5, scale * (d / pinchDist)));
          clamp(); apply();
        }
        pinchDist = d;
      }
    }, { passive: false });
    viewport.addEventListener('touchend', () => { pinchDist = 0; });

    // Scroll to zoom (desktop)
    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();
      scale = Math.max(fitScale, Math.min(fitScale * 5, scale * (e.deltaY < 0 ? 1.1 : 0.9)));
      clamp(); apply();
    }, { passive: false });

    overlay.querySelector('#crop-cancel').onclick = () => {
      URL.revokeObjectURL(url);
      overlay.remove();
    };
    overlay.querySelector('#crop-save').onclick = () => {
      const size = 512;
      const canvas = document.createElement('canvas');
      canvas.width = size; canvas.height = size;
      const ctx = canvas.getContext('2d');
      // Map viewport coords back to image coords
      const dispW = img.naturalWidth * scale, dispH = img.naturalHeight * scale;
      const sx0 = (dispW / 2 - vw / 2 - ox) / scale;
      const sy0 = (dispH / 2 - vw / 2 - oy) / scale;
      const sSize = vw / scale;
      ctx.drawImage(img, sx0, sy0, sSize, sSize, 0, 0, size, size);
      canvas.toBlob((blob) => {
        URL.revokeObjectURL(url);
        overlay.remove();
        if (blob) onCrop(new File([blob], 'photo.jpg', { type: 'image/jpeg' }));
      }, 'image/jpeg', 0.88);
    };
  };
  img.src = url;
}

/* POST a single file via multipart (no JSON content-type — browser sets the boundary) */
async function apiUploadOnce(path, file, field, extra) {
  const fd = new FormData();
  fd.append(field || 'photo', file);
  // Extra multipart fields ride along (the Solo/Co-Star declaration).
  if (extra) for (const k of Object.keys(extra)) fd.append(k, extra[k]);
  const headers = {};
  if (S.token) headers['Authorization'] = 'Bearer ' + S.token;
  const r = await fetch('/api' + path, { method: 'POST', headers, body: fd });
  let data = {};
  try { data = await r.json(); } catch (e) { /* non-JSON */ }
  return { status: r.status, data };
}

/* ---------- Public-display consent door (CCBill, Oct 27 2026) ------
 * A model whose account predates the signup consent box (no
 * publicity_consent_at stamp) meets this one-time door before her
 * next media upload; Accept stamps the consent server-side and the
 * upload proceeds. Declining cancels the upload. */
const PUB_CONSENT_UPLOAD_PATHS = ['/model/photo', '/model/public-photo', '/model/preview-video', '/model/preview-video-2', '/model/gallery-photo', '/model/feed/photo', '/model/feed/video'];
function needsPublicityConsent(path) {
  if (!S.user || S.user.role !== 'model' || S.user.publicity_consent_at) return false;
  return PUB_CONSENT_UPLOAD_PATHS.includes(path) || path === '/media/send' || path.startsWith('/model/packages/');
}
let pubConsentDoorBusy = false;
function openPublicityConsentDoor() {
  return new Promise((resolve) => {
    if (pubConsentDoorBusy) return resolve(false);
    pubConsentDoorBusy = true;
    const ov = document.createElement('div');
    ov.style.cssText = 'position:fixed;inset:0;z-index:170;background:rgba(16,6,12,.72);display:flex;align-items:center;justify-content:center;padding:20px';
    ov.innerHTML = `
      <div class="card" style="max-width:420px;width:100%;text-align:left;border:2px solid var(--pink)">
        <div style="font-weight:800;margin-bottom:6px">📣 ${t('pub_consent_h')}</div>
        <label class="checkbox-row"><input type="checkbox" id="pub-consent-check">
          <span>${t('pub_consent_body')}</span></label>
        <div class="small muted" style="margin-top:6px">${t('pub_consent_note')}</div>
        <div class="row" style="gap:8px;margin-top:14px">
          <button class="btn ghost" id="pub-consent-cancel" style="flex:1">${t('pub_consent_cancel')}</button>
          <button class="btn" id="pub-consent-accept" style="flex:2" disabled>${t('pub_consent_accept')}</button>
        </div>
      </div>`;
    document.body.appendChild(ov);
    const done = (v) => { ov.remove(); pubConsentDoorBusy = false; resolve(v); };
    const check = ov.querySelector('#pub-consent-check');
    const accept = ov.querySelector('#pub-consent-accept');
    accept.style.opacity = .4;
    check.onchange = () => { accept.disabled = !check.checked; accept.style.opacity = check.checked ? 1 : .4; };
    ov.querySelector('#pub-consent-cancel').onclick = () => done(false);
    accept.onclick = async () => {
      const { status, data } = await api('/me/publicity-consent', { method: 'POST', body: '{}' });
      if (status === 200) {
        if (S.user) S.user.publicity_consent_at = data.publicity_consent_at || 'set';
        done(true);
      } else {
        toast(t('err_publicity_consent'));
        done(false);
      }
    };
  });
}

async function apiUpload(path, file, field, extra) {
  if (needsPublicityConsent(path)) {
    const ok = await openPublicityConsentDoor();
    if (!ok) return { status: 403, data: { error: 'publicity_consent_required' } };
  }
  let result = await apiUploadOnce(path, file, field, extra);
  if (result.status === 403 && result.data && result.data.error === 'publicity_consent_required'
      && S.user && S.user.role === 'model') {
    const ok = await openPublicityConsentDoor();
    if (ok) result = await apiUploadOnce(path, file, field, extra);
  }
  return result;
}

async function ensureGuest() {
  if (S.guestToken) return S.guestToken;
  const { data } = await api('/guest/token', { method: 'POST' });
  if (data.guest_token) {
    S.guestToken = data.guest_token;
    localStorage.setItem('wc_guest', S.guestToken);
  }
  return S.guestToken;
}

/* ---------------- websocket ---------------- */

function wsConnect() {
  if (S.ws) { try { S.ws.close(); } catch (e) {} S.ws = null; }
  const q = S.token ? `token=${S.token}` : (S.guestToken ? `guest_token=${S.guestToken}` : null);
  if (!q) return;
  const proto = location.protocol === 'https:' ? 'wss' : 'ws';
  const ws = new WebSocket(`${proto}://${location.host}/ws?${q}`);
  S.ws = ws;

  ws.onmessage = (ev) => {
    let m;
    try { m = JSON.parse(ev.data); } catch (e) { return; }
    handleWS(m);
  };
  ws.onclose = () => {
    // Reconnect after 4s if we're still "logged in" somehow
    setTimeout(() => { if (S.token || S.guestToken) wsConnect(); }, 4000);
  };
}

function handleWS(m) {
  if (m.type && m.type.startsWith('booking:')) { handleBookingPush(m); return; }
  if (m.type === 'chat:new' && S.view === 'chat' && S.conv && m.conversation_id === S.conv.id) {
    // Incremental: append the one bubble; scroll only if he was already
    // at the bottom (never yank him out of history he's reading).
    const nearBottom = chatNearBottom();
    if (!S.messages.find((x) => x.id === m.message.id)) S.messages.push(m.message);
    appendMessageBubble(m.message);
    if (nearBottom) pinChatScroll();
    api(`/conversations/${S.conv.id}/read`, { method: 'POST' })
      .then(() => refreshTabBadges()).catch(() => {});
    // TikTok-style gift: emoji flies across the screen for both sides
    const gg = giftOf(m.message);
    if (gg) flyGiftAnim(gg.emoji, m.message.sender_name || 'Someone', gg.name);
  } else if (m.type === 'chat:new') {
    refreshTabBadges();
  } else if (m.type === 'pkgreq:message' || m.type === 'pkgreq:new' || m.type === 'pkgreq:update') {
    // Package request thread: re-render in place, but never eat a
    // half-typed reply — a non-empty composer defers the refresh.
    if (S.view === 'pkgRequest' && m.request_id) {
      const inp = $('#pk-input');
      if (!inp || !inp.value) show('pkgRequest', { id: m.request_id });
    } else if (S.view === 'fanChats' || S.view === 'modelChats') {
      show(S.view, {});
    }
    refreshTabBadges();
  } else if (m.type === 'pkgorder:update') {
    refreshTabBadges();
  } else if (m.type === 'chat:deleted' && S.view === 'chat' && S.conv && m.conversation_id === S.conv.id) {
    // A fan picture the model deleted in her thread disappears from
    // both sides in place.
    S.messages = S.messages.filter((x) => x.id !== m.message_id);
    renderMessages();
  } else if (m.type === 'chat:read' && S.view === 'chat' && S.conv && m.conversation_id === S.conv.id) {
    // Read receipts flip in place — a full rebuild just to turn ✓ blue
    // was part of the send/receive glitch.
    S.messages.forEach((x) => {
      if (!x.is_read) {
        x.is_read = 1;
        if (S.user && x.sender_id === S.user.id) updateMessageBubble(x);
      }
    });
  } else if (m.type === 'message:reaction' && S.view === 'chat' && S.conv && m.conversation_id === S.conv.id) {
    // Targeted bubble update — never a full re-render, never a scroll yank.
    const msg = S.messages.find((x) => x.id === m.message_id);
    if (msg) {
      msg.reactions = (m.reactions || []).map((r) => ({
        emoji: r.emoji, user_id: r.user_id, mine: S.user ? r.user_id === S.user.id : false,
      }));
      updateMessageBubble(msg);
    }
  } else if (m.type === 'message:edited' && S.view === 'chat' && S.conv && m.conversation_id === S.conv.id) {
    const msg = S.messages.find((x) => x.id === m.message_id);
    if (msg) {
      msg.body = m.body;
      msg.edited = true;
      msg.edited_at = m.edited_at;
      if (editingMsgId !== msg.id) updateMessageBubble(msg);
    }
  } else if (m.type === 'typing' && S.view === 'chat' && S.conv && m.conversation_id === S.conv.id) {
    const el = $('#typing-ind');
    if (el) el.classList.toggle('hidden', !m.is_typing);
  } else if (m.type === 'chat:paused' && S.conv && m.conversation_id === S.conv.id) {
    S.conv.is_paused = true;
    show('chat', { conv: S.conv, keepMessages: true });
    toast(m.warning || '⚠️ Chat paused');
  } else if (m.type === 'chat:resumed' && S.conv && m.conversation_id === S.conv.id) {
    S.conv.is_paused = false;
    show('chat', { conv: S.conv, keepMessages: true });
    toast('✅ Chat resumed');
  } else if (m.type === 'signal') {
    handleSignal(m);
  } else if (m.type === 'call:tick' && S.call && m.call_id === S.call.id) {
    S.call.minutes = m.minutes_billed;
    if (m.remaining_min != null) S.call.remainingMin = m.remaining_min;
    updateCallHUD();
    if (m.balance_cents != null && S.wallet) { S.wallet.credits_cents = m.balance_cents; }
  } else if (m.type === 'call:ended' && S.call && m.call_id === S.call.id) {
    endCallUI(m.reason === 'spend_cap_reached'
      ? t('spend_cap_ended')
      : m.reason === 'insufficient_credits'
      ? 'Out of credits — call ended.'
      : m.reason === 'fan_no_show'
        ? (S.call.role === 'model'
          ? '💔 He never showed up — the booking is paid, you keep it.'
          : "💔 You missed the 1-on-1 — no-shows aren't refunded.")
      : m.reason === 'time_up' ? "⏰ Time's up — video call over!" : 'Call ended.');
  } else if (m.type === 'facetime:request') {
    if (S.user && S.user.role === 'model') showFtRequestCard(m.request);
  } else if (m.type === 'facetime:update') {
    if (S.user && S.user.role === 'fan') updateFtPanel(m.request, m.reason);
    if (S.user && S.user.role === 'model') refreshFtCard();
  } else if (m.type === 'queue:update') {
    if (S.user && S.user.role === 'fan') updateFtPanel(m.request, m.reason);
  } else if (m.type === 'queue:your_turn') {
    if (S.user && S.user.role === 'fan') {
      updateFtPanel(m.request, m.reason);
      toast(`💚 Your turn! ${m.request.model_name} is ready — tap ${t('bk_start_now')}`, 5000);
    }
  } else if (m.type === 'facetime:queue') {
    if (S.user && S.user.role === 'model') updateModelFtQueue(m.requests || []);
  } else if (m.type === 'call:explicit_offer' && S.call && m.call_id === S.call.id) {
    showExplicitOffer(m);
  } else if (m.type === 'call:explicit_on' && S.call && m.call_id === S.call.id) {
    S.call.explicit = true;
    S.call.explicitPending = false;
    syncExplicitBtn();
    toast('🔞 Explicit mode ON');
  } else if (m.type === 'call:explicit_declined') {
    if (S.call) S.call.explicitPending = false;
    syncExplicitBtn();
    toast('He passed on explicit — keeping it normal.');
  } else if (m.type === 'notification:new' && m.notification) {
    refreshNotifBadge();
    toast(m.notification.title, 4000);
    if (m.notification.type === 'live' && S.view === 'notifications') show('notifications', {});
  } else if (m.type === 'tip:received' && S.user && S.user.role === 'model') {
    showGiftAnim(m.emoji, m.fan_name);
    toast(`💰 ${m.fan_name} tipped ${m.emoji} ${m.label} (${fmt(m.price_cents)})!`, 4000);
    if (typeof refreshMe === 'function') refreshMe();
  } else if (m.type === 'media:unlocked' && S.view === 'chat' && S.conv && m.conversation_id === S.conv.id) {
    toast(`💰 ${fmt(m.amount_cents)} unlock! Nice!`);
    if (S.user && S.user.role === 'model') refreshMe();
  } else if (m.type === 'battle:invite') {
    onBattleInvite(m.battle);
  } else if (m.type === 'battle:update') {
    onBattleUpdate(m.battle);
  } else if (m.type === 'battle:finished') {
    onBattleFinished(m.battle, m.your_cents);
  } else if (m.type === 'battle:chat') {
    onBattleChatMsg(m.message);
  } else if (m.type === 'battle:due') {
    toast('⚔️ ' + t('battle_schedule') + ' — ' + t('battle_ready'), 5000);
    onBattleUpdate(m.battle);
  } else if (m.type === 'live-signal') {
    if (!routeBattleSignal(m)) handleLiveSignal(m);
  } else if (m.type === 'live:viewer-joined' && S.live && S.live.role === 'model' && m.session_id === S.live.sessionId) {
    if (m.via_relay) { liveRelayViewers.add(m.fan_id); updateLiveViewerCount(); }
    else liveModelAddViewer(m.fan_id);
  } else if (m.type === 'live:viewer-left' && S.live && S.live.role === 'model' && m.session_id === S.live.sessionId) {
    liveModelRemoveViewer(m.fan_id);
  } else if (m.type === 'live:explicit' && S.live && S.live.role === 'fan' && m.session_id === S.live.sessionId) {
    if (m.explicit_entry_cents) S.live.entryCents = m.explicit_entry_cents;
    onLiveExplicitSignal(m.is_explicit, m.explicit_rate_cents, 'manual');
    // Game Category: explicit rows unlock/lock live with her mode
    if ($('#game-sheet')) renderGameSheetBody();
  } else if (m.type === 'live:brb' && S.live && m.session_id === S.live.sessionId) {
    applyLiveBrb(!!m.brb);
  } else if (m.type === 'live:ended' && S.live && m.session_id === S.live.sessionId) {
    endLiveView('Stream ended.');
  } else if (m.type === 'live:killed') {
    // Safety bot ended the stream — say why (live:ended handles teardown)
    toast(m.warning || '🛑 Stream ended by the safety bot.', 6000);
  } else if (m.type === 'live:speech_warning') {
    toast(m.warning || '⚠️ Watch what you say on live.', 5000);
  } else if (m.type === 'live:tick' && S.live && S.live.role === 'fan' && m.session_id === S.live.sessionId) {
    S.live.paying = true;
    S.live.entryPaid = true; // per-minute billing implies entry-paid server-side
    if (m.balance_cents != null && S.wallet) S.wallet.credits_cents = m.balance_cents;
    updateLivePayHUD();
  } else if (m.type === 'live:pay_stopped' && S.live && S.live.role === 'fan' && m.session_id === S.live.sessionId) {
    S.live.paying = false;
    if (m.balance_cents != null && S.wallet) S.wallet.credits_cents = m.balance_cents;
    updateLivePayHUD();
    if (S.live.isExplicit && !isGiftClear(S.live)) {
      if (m.reason === 'spend_cap_reached') toast(t('spend_cap_ended'), 4500);
      else toast('Out of credits — back to free preview.');
      applyLiveBlur(true, S.live.explicitRate, 'manual');
    } else if (!S.live.isExplicit) {
      applyLiveBlur(false);
    }
    // else: gift grace still active → stays unblurred
  } else if (m.type === 'live:chat' && S.live && m.message && m.message.session_id === S.live.sessionId) {
    S.live.chat = S.live.chat || [];
    S.live.chat.push(m.message);
    renderStreamChat();
  } else if (m.type === 'live:chat_blocked' && S.live && m.session_id === S.live.sessionId) {
    toast(m.warning || '⚠️ Message blocked', 3500);
  } else if (m.type === 'live:gift' && S.live && m.session_id === S.live.sessionId) {
    // Animated gift overlay for everyone watching + stacked ticker
    showGiftAnim(m.gift.emoji, m.fan_name);
    pushGiftStack(m.gift.emoji, m.fan_name);
    pushGiftToChat(m.gift, m.fan_name);
    if (m.balance_cents != null && S.wallet &&
        S.user && S.user.role === 'fan' && S.user.id === m.fan_id) {
      S.wallet.credits_cents = m.balance_cents;
    }
    if (S.user && S.user.role === 'model') {
      toast(`🎁 ${m.fan_name} sent ${m.gift.emoji} ${m.gift.name} (${fmt(m.gift.price_cents)})!`);
      refreshMe();
    }
    loadLeaderboard();
  } else if (m.type === 'live:priority' && S.live && m.session_id === S.live.sessionId) {
    // Paid priority banner — one at a time, dedup by id (our own expiry-fetch may race this)
    if (m.priority && m.priority.id !== S.live.priorityId) showPriorityBanner(m.priority);
  } else if (m.type === 'live:stage' && S.live && m.session_id === S.live.sessionId) {
    // Someone joined/left the stage
    if (S.live.role === 'fan') {
      if (m.stage && m.stage.fan_id === S.user.id) {
        // Our own approval arrives via live:join-approved; ignore duplicate
      } else if (m.stage) {
        showStageNotice(m.stage.fan_name, m.stage.mode);
      } else {
        hideStageBanner();
      }
    }
  } else if (m.type === 'live:join-approved' && S.live && S.live.role === 'fan' && m.session_id === S.live.sessionId) {
    onStageApproved({ fan_id: S.user.id, stage_ends_at: m.stage_ends_at, mode: m.mode }, false);
  } else if (m.type === 'live:join-declined' && S.live && S.live.role === 'fan' && m.session_id === S.live.sessionId) {
    S.live.stagePending = false;
    if (m.balance_cents != null && S.wallet) S.wallet.credits_cents = m.balance_cents;
    hideStageBanner();
    toast(`She passed this time 😅 — ${fmt(m.refunded_cents || 0)} refunded to your wallet.`, 3500);
  } else if (m.type === 'live:stage-ended' && S.live && S.live.role === 'fan' && m.session_id === S.live.sessionId) {
    stopStageStream();
    showStageBanner('ended');
    if (m.reason === 'timeout') toast("⏰ Stage time's up! She loved it though 😏", 3500);
    else if (m.reason === 'dropped') toast('She moved on — thanks for the show! 🎥', 3000);
  } else if (m.type === 'live:join-request' && S.live && S.live.role === 'model' && m.session_id === S.live.sessionId) {
    renderStageRequests();
    const reqMode = (m.request && m.request.mode) || 'video';
    const fee = stageJoinFee(!!m.request.is_explicit, reqMode);
    // Show a dedicated modal with big buttons — impossible to miss or block
    showStageRequestModal(m.request, fee);
    // Fallback: if the API call fails, render from WS data directly
    setTimeout(() => {
      const box = $('#stage-requests');
      if (box && !box.innerHTML.trim() && m.request && m.request.id) {
        const r = m.request;
        const mode = r.mode || 'video';
        box.innerHTML = `
        <div class="stage-req-card">
          <span class="grow">${stageModeEmoji(mode)} <b>${esc(r.fan_name)}</b> wants to join (${stageModeLabel(mode)})${r.is_explicit ? ' 🔞' : ''}
            <span class="muted small">(${fmt(fee)})</span></span>
          <button class="btn small" data-approve="${r.id}">✅</button>
          <button class="btn small danger" data-decline="${r.id}">❌</button>
        </div>`;
        box.querySelectorAll('[data-approve]').forEach((b) => {
          b.onclick = () => stageApprove(parseInt(b.dataset.approve));
        });
        box.querySelectorAll('[data-decline]').forEach((b) => {
          b.onclick = () => stageDecline(parseInt(b.dataset.decline));
        });
      }
    }, 1000);
  } else if (m.type === 'live:join-request-cancelled' && S.live && S.live.role === 'model' && m.session_id === S.live.sessionId) {
    renderStageRequests();
  } else if (m.type === 'game:request' && S.live && m.session_id === S.live.sessionId) {
    // His name + his request splash across BOTH stages
    showGameSplash(m);
    if (S.live.role === 'model') {
      refreshGameBadge();
      if ($('#game-sheet') && gameEditId == null) renderGamePanelBody();
      if (typeof refreshMe === 'function') refreshMe();
    }
  } else if (m.type === 'game:now' && S.live && m.session_id === S.live.sessionId) {
    showGameNow(m);
  } else if (m.type === 'game:update' && S.live && m.session_id === S.live.sessionId) {
    if (S.live.gameNowId === m.request_id) clearGameNow();
    if (S.live.role === 'model') {
      refreshGameBadge();
      if ($('#game-sheet') && gameEditId == null) renderGamePanelBody();
    }
  } else if (m.type === 'game:state' && S.live && m.session_id === S.live.sessionId) {
    S.live.gameOn = !!m.game_on;
    if ($('#game-sheet') && S.live.role === 'fan') renderGameSheetBody();
  } else if (m.type === 'game:refunded' && S.live && m.session_id === S.live.sessionId) {
    if (m.balance_cents != null && S.wallet) S.wallet.credits_cents = m.balance_cents;
    toast(t('game_refunded_toast', { label: m.label || '' }), 4000);
  } else if (m.type === 'withdrawal:decided' && S.user && (S.user.role === 'model' || S.user.role === 'recruiter')) {
    if (m.status === 'paid') toast(`💸 ${fmt(m.amount_cents)} is on its way to your bank!`, 4000);
    else toast(`Withdrawal ${fmt(m.amount_cents)} was not approved${m.note ? ': ' + m.note : ''} — funds are still available.`, 4000);
    if (S.view === 'modelEarnings') show('modelEarnings', {});
    if (S.view === 'recruiter') show('recruiter', {});
  }
}

/* ---------------- router ---------------- */

const TABS = {
  fan: [
    { id: 'models', ico: '🔥', lk: 'tab_models', view: 'fanModels' },
    { id: 'live', ico: '🔴', lk: 'tab_live', view: 'fanLive' },
    { id: 'chats', ico: '💬', lk: 'tab_chats', view: 'fanChats' },
    { id: 'book', ico: '📅', lk: 'tab_bookings', view: 'bookings' },
    { id: 'wallet', ico: '💰', lk: 'tab_wallet', view: 'wallet' },
    { id: 'playlist', ico: '🎵', lk: 'tab_playlist', view: 'playlist' },
  ],
  model: [
    { id: 'home', ico: '🏠', lk: 'tab_home', view: 'fanModels' },
    { id: 'chats', ico: '💬', lk: 'tab_chats', view: 'modelChats' },
    { id: 'book', ico: '📅', lk: 'tab_bookings', view: 'bookings' },
    { id: 'earn', ico: '💵', lk: 'tab_earnings', view: 'modelEarnings' },
    { id: 'settings', ico: '⚙️', lk: 'tab_settings', view: 'modelSettings' },
  ],
  recruiter: [], // Affiliates get a single-page dashboard — no tabs
};

function renderTabbar() {
  if (!S.user) { tabbar.classList.add('hidden'); tabbar.innerHTML = ''; return; }
  const inPreview = isFanPreview();
  const tabs = inPreview ? TABS.fan : (TABS[S.user.role] || []);
  tabbar.classList.remove('hidden');
  tabbar.innerHTML = tabs.map((tab) =>
    `<button data-tab="${tab.id}" class="${S.view === tab.view ? 'active' : ''}">
       <span class="ico">${tab.ico}</span>${t(tab.lk)}<span class="badge hidden" id="badge-${tab.id}"></span>
     </button>`).join('');
  tabbar.querySelectorAll('button').forEach((b) => {
    b.onclick = () => {
      const tab = tabs.find((x) => x.id === b.dataset.tab);
      show(tab.view, {});
    };
  });
}

/* ---------------- Admin: preview the app as a fan ----------------
   Corry checks how the fan pages look after every update WITHOUT signing
   out of the moderator account (no more fandemo round-trip). Browse-only:
   fan actions (follow / join / chat / buy) are server-gated to real fans,
   so tiles open the same look-only peek card models get, and the account
   pages (chats / bookings / wallet) show a placeholder instead of 403s. */
function isFanPreview() {
  return !!(S.user && S.user.role === 'admin' && S.previewFan);
}
function enterFanPreview() {
  if (!S.user || S.user.role !== 'admin') return;
  S.previewFan = true;
  show('fanModels', {});
}
function exitFanPreview() {
  // The moderator panel no longer lives in this app — it's Slut Manager.
  location.href = '/manager';
}
/* Pinned strip at the very top of the phone column — rendered on every
   show() while previewing, so there's always a one-tap way back. */
function renderPreviewBanner() {
  const phone = document.getElementById('phone');
  let bar = document.getElementById('preview-banner');
  if (isFanPreview()) {
    if (!bar && phone) {
      bar = document.createElement('div');
      bar.id = 'preview-banner';
      bar.className = 'preview-banner';
      bar.textContent = '👁 You\'re previewing the fan view — tap to return to Slut Manager';
      bar.onclick = exitFanPreview;
      phone.insertBefore(bar, phone.firstChild);
    }
  } else if (bar) {
    bar.remove();
  }
}
function vPreviewPlaceholder() {
  const label = { fanChats: '💬 Chats', bookings: '📅 Bookings', wallet: '💰 Wallet', playlist: '🎵 My Playlist' }[S.view] || 'This page';
  app.innerHTML = `
    <div class="header"><h1>${label}</h1></div>
    <div class="screen">
      <div class="empty"><div class="big">👁</div>Preview mode — switch back to Slut Manager to use your admin tools.<br>
        <span class="small">This page runs on a fan's own account, so there's nothing to show while you preview. The home grid and Live pages up top are fully browsable.</span></div>
      <button class="btn" id="preview-exit" style="width:100%;margin-top:14px">🛡️ Back to Slut Manager</button>
    </div>`;
  const b = $('#preview-exit');
  if (b) b.onclick = exitFanPreview;
}

/* Manager-account interstitial: signing in to the PUBLIC app with the
   manager account lands here — never silently inside the app. "Open Slut
   Manager" is the big deliberate action; "Continue" drops into the fan
   preview on purpose. */
function vManagerGate() {
  tabbar.classList.add('hidden');
  app.innerHTML = `
    <div class="header"><h1>Slut<span class="logo">Camp</span></h1>
      <div class="sub">Manager account</div></div>
    <div class="screen">
      <div class="card" style="text-align:center;padding:22px 16px">
        <img src="/img/lips-logo.png" alt="" style="width:72px;height:72px;border-radius:50%;border:2px solid var(--pink);box-shadow:0 0 18px rgba(255,92,158,.45)">
        <div style="font-weight:800;font-size:19px;margin:12px 0 6px">You're signed in with the manager account</div>
        <div class="muted small">Management lives in its own app now — Slut Manager — so it never mixes with the fan side.</div>
        <button class="btn" id="mg-open" style="width:100%;margin-top:16px;padding:15px;font-size:16px;font-weight:800">Open Slut Manager</button>
        <button class="btn ghost" id="mg-continue" style="width:100%;margin-top:10px">Continue to the app</button>
        <button class="btn ghost" id="mg-logout" style="width:100%;margin-top:6px">Log out</button>
      </div>
    </div>`;
  $('#mg-open').onclick = () => { location.href = '/manager'; };
  $('#mg-continue').onclick = () => enterFanPreview();
  $('#mg-logout').onclick = () => logout();
}

/* Home-screen icon badge (Badging API): mirrors the in-app unread total
   onto the installed app's icon. Feature-detected — where the API does
   not exist this is a silent no-op. Best-effort only, never throws. */
function updateAppBadge(n) {
  try {
    if (!('setAppBadge' in navigator)) return;
    let p = null;
    if (n > 0) p = navigator.setAppBadge(n);
    else if ('clearAppBadge' in navigator) p = navigator.clearAppBadge();
    else p = navigator.setAppBadge(0);
    if (p && p.catch) p.catch(() => {});
  } catch (e) { /* badge is best-effort */ }
}

async function refreshTabBadges() {
  if (!S.user) return;
  try {
    const { data } = await api('/conversations');
    const total = (data.conversations || []).reduce((n, c) => n + (c.unread_count || 0), 0);
    ['chats'].forEach((id) => {
      const b = document.getElementById('badge-' + id);
      if (b) { b.textContent = total; b.classList.toggle('hidden', !total); }
    });
    updateAppBadge(total);
  } catch (e) { /* ignore */ }
}

const MODEL_VIEWS = ['modelChats', 'modelEarnings', 'modelSettings', 'bookings', 'liveBroadcast', 'chat', 'pkgRequest'];

function show(view, params) {
  // Any show() navigation means a pre-login entry form was left behind.
  entryRerender = null;
  // Gate: unsigned models must sign the contract first
  if (S.user && S.user.role === 'model' && S.contractSigned === false
      && view !== 'modelContract' && MODEL_VIEWS.includes(view)) {
    view = 'modelContract';
  }
  // Gate: models with no WOGENT release on file sign at the door —
  // the release screen is the only model surface they can reach
  // until they tap I Agree (no later, no dismiss).
  if (S.user && S.user.role === 'model' && S.releaseSigned === false
      && view !== 'releaseGate' && view !== 'modelContract' && MODEL_VIEWS.includes(view)) {
    view = 'releaseGate';
  }
  S.view = view;
  S.viewParams = params || {};
  // Inside a DM conversation the bottom tab bar vanishes for the WHOLE
  // visit (owner: "too crowded when I'm in the chat") — driven off the
  // view itself, so every exit path (‹ back, tab switch, logout, any
  // programmatic show()) restores it. CSS unions this with body.sheet-open:
  // the bar is hidden when EITHER state holds, so a sheet closing inside
  // a chat can never resurrect it, and leaving a chat with a sheet open
  // keeps it hidden only until the sheet closes.
  document.body.classList.toggle('in-chat', view === 'chat');
  document.body.classList.toggle('in-live', view === 'liveBroadcast' || view === 'liveWatch');
  // The fan home gets its own mark: its header carries the Log out pill
  // the floating bell stacks under while seasonal strips are up (the
  // bell-drop rules live with .notif-bell in styles.css; the layout
  // contract is written out at .home-head-row there).
  document.body.classList.toggle('in-home', view === 'fanModels');
  // Every view change passes through here: drop any live-band keyboard
  // tracking (and its transform) before the old band leaves the DOM.
  untrackLiveBand();
  renderTabbar();
  renderPreviewBanner();
  renderBell();
  window.scrollTo(0, 0);
  const VIEWS = {
    landing: vLanding, auth: vAuth,
    fanModels: vFanModels, fanLive: vFanLive, lives: vLives, fanChats: vFanChats, wallet: vWallet, playlist: vPlaylist, quickSignup: vQuickSignup,
    modelChats: vModelChats, modelEarnings: vModelEarnings, modelSettings: vModelSettings,
    housePromos: vHousePromos,
    chat: vChat,
    liveBroadcast: vLiveBroadcast, liveWatch: vLiveWatch, battleStage: vBattleStage,
    bookings: vBookings, terms: vTerms, privacy: vPrivacy, billing: vBilling, statement2257: vStatement2257,
    managerGate: vManagerGate, modelContract: vModelContract, releaseGate: vReleaseGate,
    recruiter: vRecruiter, notifications: vNotifications, dmca: vDmca, complaints: vComplaints,
    affiliateAttach: vAffiliateAttach, affiliateMerge: vAffiliateMerge,
    privateEvent: vPrivateEvent,
    pkgRequest: vPackageRequest,
  };
  // Fan-preview placeholders: chats/bookings/wallet run on a fan's own data
  // and would 403 for an admin token — show the friendly note instead.
  const viewFn = (isFanPreview() && ['fanChats', 'bookings', 'wallet', 'playlist'].includes(view))
    ? vPreviewPlaceholder
    : (VIEWS[view] || vLanding);
  viewFn(params || {});
  if (view === 'liveBroadcast' || view === 'liveWatch' || view === 'battleStage') tabbar.classList.add('hidden');
  else if (S.user) refreshTabBadges();
}

/* ---------------- Home tiles — promo-style "who's live" video tiles ----------------
   Media fills the tile: her loop video when she has one, else her photo, else a
   gradient initial. LIVE pill + viewer count are REAL data from /api/models
   (live_session_id + live_viewers counted from live_viewers rows) — never faked. */
function tileGradient(name) {
  const hues = [[265, 320], [300, 340], [220, 280], [280, 310]];
  const h = hues[(name || '?').length % hues.length];
  return `linear-gradient(135deg,hsl(${h[0]},70%,55%),hsl(${h[1]},65%,50%))`;
}

/* Visible rank labels (owner, Oct 16 2026; per-section ladders, owner
 * ruling Oct 19 2026): a model's tile badge number is her TRUE position
 * in the composite rank order OF HER OWN SECTION (rank_position from
 * /api/models — never her index in the payload, which floats the
 * featured model to the top). Only positions 1–10 are labeled. Pure —
 * unit-tested. */
function rankBadgeFor(m) {
  const n = m && m.rank_position;
  return Number.isInteger(n) && n >= 1 && n <= 10 ? n : 0;
}

/* Rank TITLES (owner, Oct 19 2026 — "We gotta make them feel super
 * special. Work for that spot."): the top 3 of EACH section's own
 * ladder wear a title on their badge instead of a bare number —
 * Female 👸 Queen / 👸 Princess / 🫅 Duchess, Male 🤴 King / 🤴 Prince
 * / 🫅 Duke, Couple 👸🤴 Royal Couple / 🤴👸 Prince & Princess /
 * 🫅 Power Couple. Positions 4–10 keep the plain #N badge. The title
 * derives from (her section, her per-section rank_position) — both
 * already in the payload — so a model shows the title from HER ladder
 * on every tab. Pure spec (no t() call) so it stays unit-testable;
 * rankTitleText renders it. */
const RANK_TITLES = {
  female: { 1: ['👸', 'rank_queen'], 2: ['👸', 'rank_princess'], 3: ['🫅', 'rank_duchess'] },
  male: { 1: ['🤴', 'rank_king'], 2: ['🤴', 'rank_prince'], 3: ['🫅', 'rank_duke'] },
  couple: { 1: ['👸🤴', 'rank_royal_couple'], 2: ['🤴👸', 'rank_prince_princess'], 3: ['🫅', 'rank_power_couple'] },
};
function rankTitleSpec(m) {
  const n = m && m.rank_position;
  if (!Number.isInteger(n) || n < 1 || n > 3) return null;
  const byPos = RANK_TITLES[m.section || 'female'];
  const hit = byPos && byPos[n];
  return hit ? { n, emoji: hit[0], key: hit[1] } : null;
}
function rankTitleText(m) {
  const spec = rankTitleSpec(m);
  return spec ? `${spec.emoji} ${t(spec.key)} #${spec.n}` : null;
}

function modelTileHTML(m, opts) {
  opts = opts || {};
  const media = m.preview_video_url
    ? `<video class="tile-media" src="${esc(m.preview_video_url)}" autoplay muted loop playsinline></video>`
    : m.photo_url
      ? `<img class="tile-media" src="${esc(m.photo_url)}" alt="" loading="lazy">`
      : `<span class="tile-media tile-letter" style="background:${tileGradient(m.display_name)}">${esc((m.display_name || '?').trim().charAt(0).toUpperCase())}</span>`;
  const status = m.is_live
    ? `<span style="color:#fda4af;font-weight:800">${t('watch_free')}</span>`
    : m.is_online
      ? `<span style="color:#6ee7b7;font-weight:700">${t('online_now')}</span>`
      : `<span style="color:rgba(255,245,247,.6)">${t('offline')}</span>`;
  // A top-3 title rides the rank badge (same suppression rules — it IS
  // the badge), and where a tile carries a title the 👑 Top Model crown
  // pill steps aside for it (owner, Oct 19 2026: the title replaces
  // the crown on the #1 tile; never stack both).
  const titleSpec = opts.rankBadge ? rankTitleSpec(m) : null;
  return `
    <button class="model-tile${opts.hero ? ' hero' : ''}" data-model="${m.id}" data-live="${m.live_session_id || ''}">
      ${media}
      <span class="tile-shade"></span>
      ${m.is_live
        ? `<span class="tile-live-pill">● LIVE</span><span class="tile-viewers">👁 ${t('watching', { n: m.live_viewers || 0 })}</span>`
        : m.is_featured ? `<span class="tile-featured-pill">${t('featured')}</span>` : ''}
      ${opts.crown && !titleSpec ? `<span class="tile-top-pill${m.is_live ? ' below-live' : ''}">${t('top_model')}</span>` : ''}
      ${opts.isNew ? `<span class="tile-new-pill${m.is_live ? ' below-viewers' : ''}">${t('new_badge')}</span>` : ''}
      ${opts.rankBadge ? `<span class="tile-rank-badge${titleSpec ? ' rank-title' : ''}${opts.isNew ? ' below-new' : ''}${m.is_live ? ' below-viewers' : ''}">${titleSpec ? esc(rankTitleText(m)) : '#' + opts.rankBadge}</span>` : ''}
      ${opts.heartHTML || ''}
      <span class="tile-info">
        <span class="tile-name">${esc(m.display_name)}</span>
        <span class="tile-sub">@${esc(m.username)} · ${status}</span>
        ${opts.hero && m.bio ? `<span class="tile-sub">${esc(m.bio).slice(0, 80)}</span>` : ''}
        <span class="tile-sub" style="color:var(--peach);font-weight:700">${t('per_msg_rate', { price: fmt(m.per_message_cents) })} · ${t('per_min_rate', { price: fmt(m.per_minute_cents) })}</span>
        <span class="tile-sub tile-counts">❤️ <span data-like-count="${m.id}">${m.like_count || 0}</span> · 👥 <span data-follow-count="${m.id}">${m.follower_count || 0}</span></span>
        ${(m.tags && m.tags.length) ? `<span class="tile-tags">${m.tags.slice(0, 3).map((tg) => `<span class="tag-chip">${esc(tg)}</span>`).join('')}</span>` : ''}
        ${opts.hero && m.schedule_summary ? `<span class="tile-sub">${t('usually_live', { s: esc(m.schedule_summary) })}</span>` : ''}
      </span>
    </button>`;
}

/* Featured model gets the big hero tile on top; everyone else fills the grid
   in the ranked order /api/models returns (likes + earnings). #1 regular wears
   the 👑 Top Model crown — the featured headliner doesn't compete. */
/* Home grid pagination (Corry, Oct 12 2026): the ranked girls chart runs
   10 to a page — Top 10 on page 1, next 10 on page 2, and so on. The
   featured headliner (hero) stays pinned above the chart on every page. */
let homePage = 1;
// Phase 5: set by "Start private room" so the normal go-live flow opens
// the room for that event (threaded into /api/live/start, then cleared).
let pendingPrivateEventId = null;
let prTrackerRange = 'all';
let prOpenTracker = null;
const HOME_PAGE_SIZE = 10;

/* ---------------- Discovery 2.0 — search / filters / tags ----------------
   The directory endpoint returns the FULL roster in one call (no server
   pagination), so search + filters + sort all run client-side over that
   payload. DISCOVERY_TAGS mirrors MODEL_TAGS in server.js — the test
   suite pins the two copies equal, so edit both or neither. */
const DISCOVERY_TAGS = [
  'New here', 'Live daily', 'Video calls', 'Voice notes',
  'Gaming', 'Gamer girl', 'Fitness', 'Cosplay',
  'Tattoos', 'Piercings', 'Latina', 'Ebony',
  'Blonde', 'Brunette', 'Redhead', 'Curvy', 'Petite', 'MILF',
];
const disc = { q: '', online: false, live: false, price: 'any', tag: '', sort: 'top', ageMin: 18, ageMax: 65 };

/* Age Preference (fan filter, Asce Oct 23 2026 — Pink-style, placed as
 * a pill in the directory filter row): the fan picks a min–max age and
 * the grid shows only models inside it. Bounds 18..65, where 65 means
 * 65 and over; the full range is the filter OFF. The choice is a
 * device-level preference (guests included) persisted in localStorage.
 * Her age comes from the payload's computed `age` (never her dob, never
 * displayed); a model with no dob on file carries age null and passes
 * every setting — she is never hidden over a data gap. */
const AGE_PREF_KEY = 'sc_age_pref';
const AGE_PREF_MIN = 18;
const AGE_PREF_MAX = 65;
function saveAgePref() {
  try {
    localStorage.setItem(AGE_PREF_KEY, JSON.stringify({ min: disc.ageMin, max: disc.ageMax }));
  } catch (e) { /* private mode — the choice just lasts the session */ }
}
(function loadAgePref() {
  try {
    const raw = localStorage.getItem(AGE_PREF_KEY);
    if (!raw) return;
    const p = JSON.parse(raw);
    const clamp = (v, dflt) => {
      const n = Number(v);
      return Number.isFinite(n) ? Math.max(AGE_PREF_MIN, Math.min(AGE_PREF_MAX, Math.round(n))) : dflt;
    };
    const lo = clamp(p && p.min, AGE_PREF_MIN);
    const hi = clamp(p && p.max, AGE_PREF_MAX);
    disc.ageMin = Math.min(lo, hi);
    disc.ageMax = Math.max(lo, hi);
  } catch (e) { /* bad stored value — full range stands */ }
})();

/* Storefront section tabs (owner pivot, final simplification
 * Oct 18 2026): a slim strip at the top of the home/directory —
 * Female / Male / Couples / All. Entry ALWAYS lands on Female, every
 * visit: browseTab is per-session state that starts at 'female' and
 * is never stored or asked. Tapping a tab re-filters the directory
 * (and lives, which read the same state) in place. */
let browseTab = 'female';
const BROWSE_TABS = ['female', 'male', 'couples', 'all'];
function sectionTabsHTML() {
  return `<div class="sec-tabs" role="tablist">${BROWSE_TABS.map((tb) =>
    `<button type="button" class="sec-tab${browseTab === tb ? ' on' : ''}" data-sectab="${tb}">${t('sf_' + tb)}</button>`).join('')}</div>`;
}
function wireSectionTabs(rerender) {
  app.querySelectorAll('[data-sectab]').forEach((b) => {
    b.onclick = () => {
      if (browseTab === b.dataset.sectab) return;
      browseTab = b.dataset.sectab;
      rerender();
    };
  });
}

/* Per-message price bands: $ = ≤$2, $$ = ≤$5, $$$ = above. */
function discPriceBand(cents) {
  const c = Number(cents) || 0;
  return c <= 200 ? 1 : c <= 500 ? 2 : 3;
}

function discActive(d) {
  return !!(d.q || d.online || d.live || d.price !== 'any' || d.tag || d.sort !== 'top'
    || (d.ageMin || 18) > 18 || (d.ageMax == null ? 65 : d.ageMax) < 65);
}

/* Pure filter + sort over the /api/models payload. The featured model is
 * NOT special-cased here — homeTilesHTML pins her hero from whatever list
 * it is handed, so she keeps the hero slot only while she matches. The
 * default sort ('top') preserves the server's composite rank order
 * (likes + earnings) untouched; 'liked' re-sorts by like count alone. */
function applyDiscovery(models, d) {
  const q = (d.q || '').trim().toLowerCase();
  const out = (models || []).filter((m) => {
    if (q && !((m.display_name || '').toLowerCase().includes(q)
      || (m.username || '').toLowerCase().includes(q))) return false;
    if (d.online && !m.is_online) return false;
    if (d.live && !m.is_live) return false;
    if (d.price !== 'any' && discPriceBand(m.per_message_cents) !== Number(d.price)) return false;
    if (d.tag && !(m.tags || []).includes(d.tag)) return false;
    /* Age Preference: only a model WITH a computed age can fall outside
     * the range — age null (no dob on file) always passes. A max of 65
     * is open-ended (65 and over), so it never excludes from above. */
    if (m.age != null) {
      const aMin = d.ageMin == null ? 18 : d.ageMin;
      const aMax = d.ageMax == null ? 65 : d.ageMax;
      if (m.age < aMin || (aMax < 65 && m.age > aMax)) return false;
    }
    return true;
  });
  const rank = (m) => m.rank_score || 0;
  if (d.sort === 'liked') out.sort((a, b) => ((b.like_count || 0) - (a.like_count || 0)) || (rank(b) - rank(a)));
  else if (d.sort === 'online') out.sort((a, b) => (Number(b.is_online) - Number(a.is_online)) || (rank(b) - rank(a)));
  else if (d.sort === 'price_low') out.sort((a, b) => (a.per_message_cents - b.per_message_cents) || (rank(b) - rank(a)));
  else if (d.sort === 'price_high') out.sort((a, b) => (b.per_message_cents - a.per_message_cents) || (rank(b) - rank(a)));
  else if (d.sort === 'newest') out.sort((a, b) => String(b.created_at || '').localeCompare(String(a.created_at || '')) || (rank(b) - rank(a)));
  return out;
}

/* "More like her": shared discovery tags first, then directory rank.
 * With no tags anywhere it degrades to the top-ranked others. */
function similarModels(m, models, n) {
  const mine = new Set(m.tags || []);
  return (models || [])
    .filter((x) => x.id !== m.id)
    .map((x) => ({ x, shared: (x.tags || []).filter((tg) => mine.has(tg)).length }))
    .sort((a, b) => (b.shared - a.shared) || ((b.x.rank_score || 0) - (a.x.rank_score || 0)))
    .slice(0, n || 6)
    .map((s) => s.x);
}

/* ---------------- "New models you may like" front-page rail ----------------
   Every new model gets her first two weeks on the front page: a rail at
   the top of the directory (fan home + guest landing) carrying the top
   NEW_MODELS_RAIL_MAX models whose accounts are younger than
   NEW_MODEL_WINDOW_DAYS. Pure client-side windowing over the /api/models
   payload's created_at (already in the payload for the Newest sort);
   the payload's order IS the directory rank, so the rail never re-sorts.
   She ages out on her own at render time — no cron, no admin toggle. */
const NEW_MODEL_WINDOW_DAYS = 14;
const NEW_MODELS_RAIL_MAX = 10;

/* created_at arrives as SQLite UTC text ('YYYY-MM-DD HH:MM:SS') — parse
 * it as UTC, not browser-local, so her two weeks end when they should.
 * Unparseable / missing → NaN → she simply never counts as new. */
function modelCreatedMs(m) {
  const s = String((m && m.created_at) || '').trim();
  if (!s) return NaN;
  const iso = s.replace(' ', 'T');
  return Date.parse(/(Z|[+-]\d{2}:?\d{2})$/i.test(iso) ? iso : iso + 'Z');
}

function newModelsRail(models, now) {
  const t = typeof now === 'number' ? now : Date.now();
  const windowMs = NEW_MODEL_WINDOW_DAYS * 24 * 3600 * 1000;
  return (models || []).filter((m) => {
    const age = t - modelCreatedMs(m);
    return age >= 0 && age < windowMs;
  }).slice(0, NEW_MODELS_RAIL_MAX);
}

/* The rail is front-page furniture only: it disappears the moment the
 * fan is searching/filtering/sorting (same rule as the Top-Model crown)
 * and renders nothing at all when nobody is inside her two weeks. */
function newModelsRailHTML(models, heartFor) {
  if (discActive(disc)) return '';
  const fresh = newModelsRail(models, Date.now());
  if (!fresh.length) return '';
  const heart = (m) => (heartFor ? heartFor(m) : '');
  return `
  <div class="new-rail-wrap">
    <div class="new-rail-title">${t('new_models_title')}</div>
    <div class="new-rail">
      ${fresh.map((m) => modelTileHTML(m, { isNew: true, heartHTML: heart(m) })).join('')}
    </div>
  </div>`;
}

/* Home controls tidy (owner design, Oct 19 2026 — "make it neat, too
 * much going on"): the bar carries ONLY Search + sort, one 🟢 Online
 * chip, and one tag dropdown. The small 🔴 Live chip is gone (the big
 * Lives button already goes to lives) and the $ / $$ / $$$ price-band
 * chips are gone (price ordering lives in the sort select, whose option
 * list is unchanged). The tag chips became a single dropdown that shows
 * the selected tag (or "All tags") and picks from the same used-tags
 * list the chips showed — it writes the very same disc.tag state, so
 * applyDiscovery composes exactly as before.
 * Round 2 (owner, later Oct 19 2026 — annotated screenshot of the live
 * home): the dropdown rides UP onto the Online row — [🟢 Online]
 * [tag dropdown filling the rest] [✖ Clear when active], all one row —
 * and the bar sits tighter over the "New models" rail (no big gap). */
function discoveryBarHTML(models) {
  const usedTags = DISCOVERY_TAGS.filter((tg) => (models || []).some((m) => (m.tags || []).includes(tg)));
  /* The selected tag stays listed even when the current section's
   * payload uses it on nobody — the control never vanishes mid-filter. */
  const tagOptions = disc.tag && !usedTags.includes(disc.tag) ? [...usedTags, disc.tag] : usedTags;
  return `
  <div class="disc-bar">
    <div class="disc-row">
      <input class="input disc-search" id="disc-q" type="search" placeholder="${t('search_models_ph')}" value="${esc(disc.q)}" autocomplete="off">
      <select class="input disc-sort" id="disc-sort">
        ${['top', 'liked', 'online', 'price_low', 'price_high', 'newest'].map((s) => `<option value="${s}" ${disc.sort === s ? 'selected' : ''}>${t('sort_' + s)}</option>`).join('')}
      </select>
    </div>
    <div class="disc-row disc-chips">
      <button class="disc-chip ${disc.online ? 'on' : ''}" data-disc-toggle="online">${t('disc_online')}</button>
      <button class="disc-chip ${(disc.ageMin > 18 || disc.ageMax < 65) ? 'on' : ''}" id="disc-age">🎂 ${(disc.ageMin > 18 || disc.ageMax < 65) ? `${disc.ageMin}–${disc.ageMax >= 65 ? '65+' : disc.ageMax}` : t('disc_age_any')}</button>
      ${tagOptions.length ? `<span class="disc-selectwrap"><select class="input disc-sort disc-tagpick" id="disc-tag" aria-label="${t('disc_tag_any')}">
        <option value="" ${disc.tag ? '' : 'selected'}>${t('disc_tag_any')}</option>
        ${tagOptions.map((tg) => `<option value="${esc(tg)}" ${disc.tag === tg ? 'selected' : ''}>${esc(tg)}</option>`).join('')}
      </select></span>` : ''}
      ${discActive(disc) ? `<button class="disc-chip clear" id="disc-clear">${t('clear_filters')}</button>` : ''}
    </div>
  </div>`;
}

/* Every control re-renders the directory view with the new state and
 * resets pagination — a filtered list always starts on page 1. */
function wireDiscovery(viewName) {
  const apply = (fn) => { fn(); homePage = 1; show(viewName, {}); };
  const q = $('#disc-q');
  if (q) q.addEventListener('change', () => apply(() => { disc.q = q.value; }));
  const so = $('#disc-sort');
  if (so) so.addEventListener('change', () => apply(() => { disc.sort = so.value; }));
  app.querySelectorAll('[data-disc-toggle]').forEach((b) => {
    b.onclick = () => apply(() => { disc[b.dataset.discToggle] = !disc[b.dataset.discToggle]; });
  });
  const tg = $('#disc-tag');
  if (tg) tg.addEventListener('change', () => apply(() => { disc.tag = tg.value; }));
  const ag = $('#disc-age');
  if (ag) ag.onclick = () => openAgeSheet(() => apply(() => {}));
  const cl = $('#disc-clear');
  if (cl) cl.onclick = () => apply(() => {
    disc.q = ''; disc.online = false; disc.live = false;
    disc.price = 'any'; disc.tag = ''; disc.sort = 'top';
    disc.ageMin = 18; disc.ageMax = 65; saveAgePref();
  });
}

/* Age Preference sheet (Pink's pattern, the app's sheet style): one
 * dual-thumb slider, live readout, Save / Cancel / Any age. Edits stay
 * local to the sheet until Save — Cancel walks away with the directory
 * untouched. "Any age" is the reset: full range, saved, done. */
function openAgeSheet(onDone) {
  let sheet = document.getElementById('ageSheet');
  if (!sheet) {
    sheet = document.createElement('div');
    sheet.id = 'ageSheet';
    sheet.className = 'lang-sheet age-sheet';
    document.body.appendChild(sheet);
    sheet.addEventListener('click', (e) => { if (e.target === sheet) closeAgeSheet(); });
  }
  let lo = disc.ageMin;
  let hi = disc.ageMax;
  sheet.innerHTML = `
    <div class="lang-sheet-card">
      <div class="lang-sheet-title">🎂 ${t('disc_age_pref')}</div>
      <div class="age-readout" id="age-readout"></div>
      <div class="age-dual">
        <div class="age-track"></div>
        <div class="age-fill" id="age-fill"></div>
        <input type="range" id="age-min" min="18" max="65" step="1" value="${lo}" aria-label="${t('disc_age_pref')}">
        <input type="range" id="age-max" min="18" max="65" step="1" value="${hi}" aria-label="${t('disc_age_pref')}">
      </div>
      <div class="age-sheet-btns">
        <button type="button" class="btn ghost" id="age-any">${t('disc_age_any')}</button>
        <button type="button" class="btn ghost" id="age-cancel">${t('cancel')}</button>
        <button type="button" class="btn" id="age-save">${t('disc_age_save')}</button>
      </div>
    </div>`;
  sheet.hidden = false;
  const minEl = sheet.querySelector('#age-min');
  const maxEl = sheet.querySelector('#age-max');
  const out = sheet.querySelector('#age-readout');
  const fill = sheet.querySelector('#age-fill');
  const paint = () => {
    out.textContent = `${lo} – ${hi >= 65 ? '65+' : hi}`;
    const span = 65 - 18;
    fill.style.left = `${((lo - 18) / span) * 100}%`;
    fill.style.width = `${((hi - lo) / span) * 100}%`;
    /* Whichever end of the range the fan is working, its thumb rides
     * on top — at a collapsed range the far thumb must stay grabbable. */
    minEl.style.zIndex = lo > 55 ? 3 : 5;
    maxEl.style.zIndex = lo > 55 ? 5 : 3;
  };
  minEl.addEventListener('input', () => {
    lo = Math.min(Number(minEl.value) || 18, hi);
    minEl.value = lo;
    paint();
  });
  maxEl.addEventListener('input', () => {
    hi = Math.max(Number(maxEl.value) || 65, lo);
    maxEl.value = hi;
    paint();
  });
  paint();
  const commit = (min, max) => {
    disc.ageMin = min;
    disc.ageMax = max;
    saveAgePref();
    closeAgeSheet();
    if (onDone) onDone();
  };
  sheet.querySelector('#age-save').onclick = () => commit(lo, hi);
  sheet.querySelector('#age-any').onclick = () => commit(18, 65);
  sheet.querySelector('#age-cancel').onclick = () => closeAgeSheet();
}
function closeAgeSheet() {
  const sheet = document.getElementById('ageSheet');
  if (sheet) sheet.hidden = true;
}

function homeTilesHTML(models, heartFor, opts) {
  const featured = models.find((m) => m.is_featured);
  const rest = featured ? models.filter((m) => m.id !== featured.id) : models;
  const heart = (m) => (heartFor ? heartFor(m) : '');
  const pages = Math.max(1, Math.ceil(rest.length / HOME_PAGE_SIZE));
  if (homePage > pages) homePage = pages;
  if (homePage < 1) homePage = 1;
  const start = (homePage - 1) * HOME_PAGE_SIZE;
  const slice = rest.slice(start, start + HOME_PAGE_SIZE);
  // The 👑 marks the #1 RANKED model — only meaningful in the default
  // (top-ranked) ordering, so filtered/sorted views suppress it. The
  // #1–#10 rank badges follow the same rule: a re-sorted or filtered
  // list must never label anyone by a position she doesn't hold.
  const crownOn = !opts || opts.crown !== false;
  const badgesOn = !opts || opts.rankBadges !== false;
  const badge = (m) => (badgesOn ? rankBadgeFor(m) : 0);
  return `
    ${featured ? modelTileHTML(featured, { hero: true, rankBadge: badge(featured), heartHTML: heart(featured) }) : ''}
    <div class="tile-grid">
      ${slice.map((m, i) => modelTileHTML(m, { crown: crownOn && start + i === 0, rankBadge: badge(m), heartHTML: heart(m) })).join('')}
    </div>
    ${pages > 1 ? `
    <div class="row" style="justify-content:center;align-items:center;gap:10px;margin-top:16px">
      <button class="btn small ghost pg-btn" data-pg="${homePage - 1}" ${homePage <= 1 ? 'disabled style="opacity:.4"' : ''}>${t('pager_prev')}</button>
      <span class="small muted">${t('pager_page', { x: homePage, y: pages })}</span>
      <button class="btn small ghost pg-btn" data-pg="${homePage + 1}" ${homePage >= pages ? 'disabled style="opacity:.4"' : ''}>${t('pager_next')}</button>
    </div>` : ''}`;
}

// Pager clicks (one delegated listener for both the guest + fan home grids)
document.addEventListener('click', (e) => {
  const b = e.target.closest('.pg-btn');
  if (!b || b.disabled) return;
  homePage = parseInt(b.dataset.pg) || 1;
  show(S.view, {});
  window.scrollTo({ top: 0, behavior: 'smooth' });
});

/* "🔴 Lives" home button — opens the Live Now grid. The count is REAL data
   from /api/models (is_live flags) — only shown when someone is truly live. */
function livesBtnHTML(models) {
  const n = (models || []).filter((m) => m.is_live).length;
  return `<button class="btn-lives${n ? ' has-live' : ''}" id="go-lives">${t('lives_btn')}${n ? `<span class="lives-count">${t('lives_count', { n })}</span>` : ''}</button>`;
}

/* The OFFICIAL house account's pinned card (owner, Oct 17 2026): the
   SlutCamp account is the app itself, not a model — it never renders
   as a model tile anywhere. Instead it stays pinned at the TOP of the
   fan home in both states: LIVE (tap joins the stream exactly like a
   live model tile; tipping/spending inside are the regular live
   machinery) and quiet (tap opens its look-only profile page — no
   Message bar, ever). Data = the `official` object on the /api/models
   payload; null (no house account) renders nothing, and because the
   server keeps the account OUT of the models array, the card can
   never duplicate as a tile. */
function officialCardHTML(official) {
  if (!official) return '';
  return `
    <button class="official-card" data-official="${official.id}">
      <span class="avatar-wrap">${avatarHTML(official.display_name, '', official.photo_url)}</span>
      <span class="grow">
        <span class="official-name">${esc(official.display_name)} <span class="official-pill">${t('official_label')}</span></span><br>
        ${official.is_live
          ? `<span class="live-badge">🔴 LIVE</span> <span class="small muted">👁 ${t('watching', { n: official.live_viewers || 0 })}</span>`
          : `<span class="small muted">${t('official_tagline')}</span>`}
      </span><span style="font-size:22px">›</span>
    </button>`;
}

/* ---------------- LANDING (public model grid) ---------------- */

async function vLanding() {
  const { data } = await api('/models');
  const models = data.models || [];
  const { data: schedData } = await api('/live/schedule');
  const house = (schedData && schedData.house) || null;
  const shown = applyDiscovery(models, disc);
  const heartFor = (m) => `
            <span class="model-likes tile-heart" data-like="${m.id}">
              <span class="like-heart">${m.liked ? '❤️' : '🤍'}</span>
              <span class="like-count" data-like-count="${m.id}">${m.like_count || 0}</span>
            </span>`;
  app.innerHTML = `
    <div class="header">
      <h1>Slut<span class="logo">Camp</span> 💬</h1>
      <div class="sub">${t('home_sub')}</div>
    </div>
    <div class="screen">
      ${houseBannerHTML(house)}
      ${sectionTabsHTML()}
      ${livesBtnHTML(models)}
      <div class="card" style="text-align:center;background:linear-gradient(135deg,#3b1d6e,#1a0f2e)">
        <div style="font-size:20px;font-weight:800">${t('free3_title')}</div>
        <div class="muted small" style="margin-top:4px">${t('free3_sub')}</div>
      </div>
      ${S.user ? '' : `
      <div class="card" style="text-align:center">
        <div style="font-size:18px;font-weight:800">${t('signin_have_account')}</div>
        <button class="btn" id="si-fan" style="width:100%;margin-top:12px">😍 ${t('signin_as_fan')}</button>
        <button class="btn" id="si-model" style="width:100%;margin-top:8px">💃 ${t('signin_as_model')}</button>
        <button class="btn" id="si-aff" style="width:100%;margin-top:8px">🤝 ${t('signin_as_affiliate')}</button>
        <div class="muted small" style="margin-top:12px">${t('signin_join_q')} <a href="javascript:void(0)" id="si-join" style="color:var(--pink);font-weight:700">${t('signin_join_free')}</a></div>
      </div>`}
      ${discoveryBarHTML(models)}
      ${newModelsRailHTML(models, heartFor)}
      ${!models.length
        ? `<div class="empty"><div class="big">😴</div>${t('no_models')}</div>`
        : shown.length ? homeTilesHTML(shown, heartFor, { crown: !discActive(disc), rankBadges: !discActive(disc) })
        : `<div class="empty"><div class="big">🔍</div>${t('no_matches')}</div>`}
      <div style="text-align:center;margin-top:10px">
        <button class="btn ghost" id="share-app" style="border-color:var(--pink);color:var(--pink)">${t('share_app')}</button>
      </div>
      <div class="lang-row">${langPillsHTML()}</div>
      <p class="muted small" style="text-align:center;margin-top:16px">${t('terms_line')} <a href="javascript:void(0)" id="go-terms" style="color:var(--pink)">${t('terms')}</a> · <a href="javascript:void(0)" id="go-privacy" style="color:var(--pink)">Privacy</a> · <a href="javascript:void(0)" id="go-billing" style="color:var(--pink)">Billing & Refunds</a> · <a href="javascript:void(0)" id="go-2257" style="color:var(--pink)">2257 Statement</a> · <a href="javascript:void(0)" id="go-dmca" style="color:var(--pink)">DMCA</a>.</p>
    </div>`;
  wireSectionTabs(() => show('landing', {}));
  wireHouseBanner();
  app.querySelectorAll('[data-model]').forEach((b) => {
    b.onclick = () => {
      const liveId = b.dataset.live;
      if (liveId) return watchLive(parseInt(liveId));
      // Her profile comes first on the front door too (owner,
      // Oct 17 2026) — the same profile-first rule as the fan home
      // grid: a tile tap opens her profile page, and the peek's
      // pinned bar carries the next step (Message for fans, join /
      // log in for guests). Straight-to-chat was the old behaviour
      // and skipped her page entirely.
      const m = models.find((x) => x.id === parseInt(b.dataset.model));
      if (m) { openModelPeek(m, models); return; }
      openChatWithModel(parseInt(b.dataset.model));
    };
  });
  // Heart likes — tap without opening chat
  app.querySelectorAll('[data-like]').forEach((h) => {
    h.onclick = async (e) => {
      e.stopPropagation();
      if (!S.user || S.user.role !== 'fan') return toast(t('like_need_fan'));
      const modelId = parseInt(h.dataset.like);
      const { status, data } = await api(`/models/${modelId}/like`, { method: 'POST' });
      if (status === 200) {
        h.querySelector('.like-heart').textContent = data.liked ? '❤️' : '🤍';
        h.querySelector('.like-count').textContent = data.like_count;
        // The same number printed in her tile's counts line moves too.
        document.querySelectorAll(`[data-like-count="${modelId}"]`).forEach((el) => { el.textContent = data.like_count; });
      }
    };
  });
  wireDiscovery('landing');
  // Role sign-in block (owner, Oct 17 2026): three big buttons, one
  // per role, straight to the login form carrying that role — the
  // old single "Log in / Sign up" button left returning users unsure
  // where to sign in. Joining lives in the same card as a quiet link.
  const siFan = $('#si-fan');
  if (siFan) siFan.onclick = () => show('auth', { mode: 'login', role: 'fan' });
  const siModel = $('#si-model');
  if (siModel) siModel.onclick = () => show('auth', { mode: 'login', role: 'model' });
  const siAff = $('#si-aff');
  if (siAff) siAff.onclick = () => show('auth', { mode: 'login', role: 'affiliate' });
  const siJoin = $('#si-join');
  if (siJoin) siJoin.onclick = () => show('auth', { mode: 'signup' });
  const lv = $('#go-lives');
  if (lv) lv.onclick = () => show('lives', {});
  const sh = $('#share-app');
  if (sh) sh.onclick = shareApp;
  const gt = $('#go-terms');
  if (gt) gt.onclick = () => show('terms', {});
  const gp = $('#go-privacy');
  if (gp) gp.onclick = () => show('privacy', {});
  const gb = $('#go-billing');
  if (gb) gb.onclick = () => show('billing', {});
  const g7 = $('#go-2257');
  if (g7) g7.onclick = () => show('statement2257', {});
  const gd = $('#go-dmca');
  if (gd) gd.onclick = () => show('dmca', {});
}

/* Share the app via native share sheet, fallback to copy link */
async function shareApp() {
  const url = canonOrigin();
  const data = { title: 'SlutCamp', text: 'Chat & video call the models on SlutCamp 🔥 18+ only', url };
  if (navigator.share) {
    try { await navigator.share(data); } catch (e) { /* user cancelled */ }
  } else if (navigator.clipboard) {
    try { await navigator.clipboard.writeText(url); toast(t('link_copied')); }
    catch (e) { toast(url); }
  } else {
    prompt('Copy your SlutCamp link:', url);
  }
}

async function openChatWithModel(modelId) {
  await ensureGuest();
  const { status, data } = await api('/conversations/start', {
    method: 'POST', body: JSON.stringify({ model_id: modelId }),
  });
  if (status === 200) { show('chat', { conv: data.conversation }); return true; }
  else if (data && data.error === 'region_blocked')
    toast('This model is not available in your region.');
  else toast('Could not open chat.');
  return false;
}

/* ---------------- AUTH ---------------- */

/* ------------------------------------------------------------------ */
/* Section router (owner pivot, Oct 18 2026): the FIRST step of every */
/* model join is one neat step — a box asking "Joining as" with       */
/* Female / Male / Couple — before any signup form, at all three      */
/* model doors (front door, Manager invite link, affiliate link).     */
/* Every pick proceeds into the model signup carrying its section;    */
/* the server refuses a model register without a valid section and    */
/* records the attestation, so the router cannot be bypassed by       */
/* calling the API directly.                                          */
/* ------------------------------------------------------------------ */
let modelSectionPick = null;

function vSectionGate(resume) {
  entryRerender = () => vSectionGate(resume);
  app.innerHTML = `
    <div class="header"><h1>Slut<span class="logo">Camp</span></h1>
      <div class="sub">${t('create_account_h')}</div></div>
    <div class="screen">
      <div class="card" style="text-align:center">
        <div style="font-size:18px;font-weight:800">${t('sec_title')}</div>
        <button class="btn" id="sec-female" style="width:100%;margin-top:14px">${t('sec_female')}</button>
        <button class="btn" id="sec-male" style="width:100%;margin-top:8px">${t('sec_male')}</button>
        <button class="btn" id="sec-couple" style="width:100%;margin-top:8px">${t('sec_couple')}</button>
      </div>
      <div class="lang-row">${langPillsHTML()}</div>
      <button class="btn ghost" id="sec-back" style="margin-top:12px">${t('back')}</button>
    </div>`;
  $('#sec-female').onclick = () => { modelSectionPick = 'female'; resume(); };
  $('#sec-male').onclick = () => { modelSectionPick = 'male'; resume(); };
  $('#sec-couple').onclick = () => { modelSectionPick = 'couple'; resume(); };
  $('#sec-back').onclick = () => show('landing', {});
}

/* ---------------- Join warning modal ----------------
   Entry-warning build, Part 2 (Asce, 2026-10-23): the FIRST tap
   that starts joining — as a fan, a model, or an affiliate /
   recruiter — pops this warning BEFORE the signup form, mirroring
   Part 1's age-gate block: same warn title + red body + agreement
   checkbox (gate_warn_h / gate_warn_body / gate_agree), Continue
   blocked until the box is ticked (gate_err_agree), Cancel goes
   back with no form opened. Acceptance is remembered for the
   current page load ONLY (this module flag — nothing is stored):
   starting a second role's signup in the same visit doesn't
   re-pop, and a fresh page load asks again. The signup forms
   keep their own DOB + agree18 fields — this modal is the
   warning layer in front, not a replacement. */
let joinWarnAccepted = false;

function joinWarningGate(proceed) {
  if (joinWarnAccepted) { proceed(); return; }
  const sheet = ftSheet(`
    <div class="age-gate-warn" style="margin-top:4px">
      <div class="age-gate-warn-h">${t('gate_warn_h')}</div>
      <p class="age-gate-warn-body">${t('gate_warn_body')}</p>
    </div>
    <label class="age-gate-agree"><input type="checkbox" id="jw-agree">
      <span>${t('gate_agree')}</span></label>
    <p id="jw-error" class="age-error hidden"></p>
    <button class="btn" id="jw-continue" style="width:100%;margin-top:14px">${t('gate_warn_continue')}</button>
    <button class="sheet-btn" id="jw-cancel">${t('cancel')}</button>`);
  sheet.querySelector('#jw-cancel').onclick = () => ftCloseSheet();
  sheet.querySelector('#jw-continue').onclick = () => {
    const box = sheet.querySelector('#jw-agree');
    if (!box || !box.checked) {
      const err = sheet.querySelector('#jw-error');
      err.textContent = t('gate_err_agree');
      err.classList.remove('hidden');
      return;
    }
    joinWarnAccepted = true;
    ftCloseSheet();
    proceed();
  };
}

function vAuth(params) {
  const mode = (params && params.mode) || 'login';
  const role = (params && params.role) || 'fan';
  // Sign-in role context (owner, Oct 17 2026): set when she arrived
  // via a "Sign in as a …" button or picked her role above the login
  // form. It labels the form ("Model sign in") and nothing more —
  // the account's stored role still decides where she lands. A bare
  // login visit carries none (null), and signup keeps its own role.
  const loginRole = mode === 'login' && ['fan', 'model', 'affiliate'].includes(params && params.role)
    ? params.role : null;
  app.innerHTML = `
    <div class="header"><h1>Slut<span class="logo">Camp</span></h1>
      <div class="sub">${mode === 'login' ? (loginRole ? t('signin_h_' + loginRole) : t('welcome_back')) : t('create_account_h')}</div></div>
    <div class="screen">
      <div class="tabs">
        <button id="t-login" class="${mode === 'login' ? 'active' : ''}">${t('log_in')}</button>
        <button id="t-signup" class="${mode === 'signup' ? 'active' : ''}">${t('sign_up')}</button>
      </div>
      <div id="auth-body"></div>
      ${mode === 'login' ? `<div class="lang-row" style="margin-top:14px">${langPillsHTML()}</div>` : ''}
      <button class="btn ghost" id="back-browse" style="margin-top:16px">${t('keep_browsing')}</button>
    </div>`;
  $('#t-login').onclick = () => show('auth', { mode: 'login', role });
  $('#t-signup').onclick = () => show('auth', { mode: 'signup', role });
  $('#back-browse').onclick = () => show('landing', {});
  renderAuthBody(mode, role, loginRole);
}

function renderAuthBody(mode, role, loginRole) {
  const body = $('#auth-body');
  if (mode === 'login') {
    body.innerHTML = `
      <div style="display:flex;flex-direction:column;gap:8px;margin-bottom:14px">
        <button class="btn ${loginRole === 'fan' ? '' : 'ghost'}" data-si-role="fan">😍 ${t('signin_as_fan')}</button>
        <button class="btn ${loginRole === 'model' ? '' : 'ghost'}" data-si-role="model">💃 ${t('signin_as_model')}</button>
        <button class="btn ${loginRole === 'affiliate' ? '' : 'ghost'}" data-si-role="affiliate">🤝 ${t('signin_as_affiliate')}</button>
      </div>
      <label class="field">${t('username')}<input class="input" id="a-user" autocomplete="username"></label>
      <label class="field">${t('password')}${pwField('a-pass', 'current-password')}</label>
      <button class="btn" id="a-go">${t('log_in')}</button>
      ${pkSupported() ? `
      <button class="btn ghost" id="a-faceid" style="width:100%;margin-top:10px">🔐 Sign in with Face ID</button>
      <div class="small muted" id="pk-login-msg" style="margin-top:8px;text-align:center"></div>` : ''}`;
    $('#a-go').onclick = doLogin;
    body.querySelectorAll('[data-si-role]').forEach((b) => {
      b.onclick = () => show('auth', { mode: 'login', role: b.dataset.siRole });
    });
    const fidBtn = $('#a-faceid');
    if (fidBtn) fidBtn.onclick = doPasskeyLogin;
  } else {
    body.innerHTML = `
      <div class="role-card ${role === 'fan' ? 'selected' : ''}" id="r-fan">
        <div class="emoji">😍</div><div class="t">${t('im_fan')}</div>
        <div class="d">${t('fan_desc')}</div></div>
      <div class="role-card ${role === 'model' ? 'selected' : ''}" id="r-model">
        <div class="emoji">💃</div><div class="t">${t('im_model')}</div>
        <div class="d">${t('model_desc')}</div></div>
      <div class="role-card ${role === 'affiliate' ? 'selected' : ''}" id="r-aff">
        <div class="emoji">🤝</div><div class="t">${t('im_affiliate')}</div>
        <div class="d">${t('affiliate_desc')}</div></div>
      <div id="auth-fields"></div>`;
    let r = ['fan', 'model', 'affiliate'].includes(role) ? role : 'fan';
    const paint = () => {
      $('#r-fan').classList.toggle('selected', r === 'fan');
      $('#r-model').classList.toggle('selected', r === 'model');
      $('#r-aff').classList.toggle('selected', r === 'affiliate');
      renderSignupFields(r);
    };
    // Join warning (Part 2): every role start routes through the
    // warning modal first — a role-card tap or the initial arrival
    // alike. The form paints only on Continue (or instantly once
    // the warning was accepted this page load). A model start keeps
    // its section-router step, which runs after the warning.
    const startModel = () => {
      // Section router (owner pivot, Oct 18 2026): the "Joining as"
      // pick comes FIRST — the model form never renders before it.
      if (!modelSectionPick) return vSectionGate(() => show('auth', { mode: 'signup', role: 'model' }));
      r = 'model'; paint();
    };
    $('#r-fan').onclick = () => joinWarningGate(() => { r = 'fan'; paint(); });
    $('#r-model').onclick = () => joinWarningGate(startModel);
    $('#r-aff').onclick = () => joinWarningGate(() => { r = 'affiliate'; paint(); });
    // Arriving with the model role pre-picked is routed the same way.
    if (r === 'model') return joinWarningGate(startModel);
    joinWarningGate(() => paint());
  }
}

/* Signup fields under the role cards. Fan/model share the standard
 * form; Affiliate gets the recruiter form — same fields, validations
 * and agreement step as the Manager affiliate-invite signup, minus
 * the invite code (existing affiliates just use the Log in tab). */
