function renderSignupFields(role) {
  const host = $('#auth-fields');
  if (!host) return;
  if (role === 'affiliate') {
    host.innerHTML = `
      <div class="card" style="background:linear-gradient(135deg,#3b1d6e,#1a0f2e);text-align:center">
        <div style="font-size:18px;font-weight:800">${t('aff_become_h')}</div>
        <div class="muted small" style="margin-top:4px">${t('aff_join_sub')}</div>
      </div>
      <label class="field">${t('your_name')}<input class="input" id="af-name" maxlength="40"></label>
      <label class="field">${t('username')}<input class="input" id="af-user" autocomplete="username"></label>
      <label class="field">${t('password_hint')}${pwField('af-pass', 'new-password')}</label>
      <div class="card" style="margin-top:12px;max-height:280px;overflow-y:auto;text-align:left">
        <div style="font-weight:800;margin-bottom:8px">${t('aff_agreement_h')}</div>
        ${affAgreementSections().map(([h, b]) => `<div style="margin-bottom:10px"><div style="font-weight:700">${esc(h)}</div><div class="small muted">${esc(b)}</div></div>`).join('')}
      </div>
      <div class="card" style="margin-top:12px;text-align:left"><div class="small">${t('aff_quota_notice')}</div></div>
      <label class="checkbox-row" style="margin-top:12px"><input type="checkbox" id="af-agree">
        <span>${t('aff_agree')}</span></label>
      <div class="lang-row">${langPillsHTML()}</div>
      <button class="btn" id="af-go">${t('aff_accept_btn')}</button>`;
    $('#af-go').onclick = doAffiliateSignup;
    return;
  }
  host.innerHTML = `
      ${role === 'fan' ? '<div id="promo-banner-slot"></div>' : ''}
      <label class="field">${t('display_name')}<input class="input" id="a-name" maxlength="40"></label>
      <label class="field">${t('username')}<input class="input" id="a-user" autocomplete="username"></label>
      <label class="field">${t('password_hint')}${pwField('a-pass', 'new-password')}</label>
      ${role === 'fan' ? `<label class="field">${t('signup_email_optional')}<input class="input" id="a-email" type="email" autocomplete="email"></label>` : ''}
      <label class="field">${t('dob')}<input class="input" id="a-dob" type="date"></label>
      <div class="age-box">🔞 <b>${t('age18_only')}</b> ${t('age18_line')}
        ${role === 'model' ? t('model_age_id_note') : t('fan_age_line')}</div>
      <label class="checkbox-row"><input type="checkbox" id="a-18">
        <span>${t('confirm18')}</span></label>
      ${role === 'model' ? pubConsentCardHTML('a') : ''}
      ${role === 'model' && modelSectionPick === 'couple' ? `
      <div class="card" style="margin-top:12px;text-align:left">
        <div style="font-weight:800;margin-bottom:4px">${t('coperf_signup_h')}</div>
        <div class="muted small" style="margin-bottom:8px">${t('coperf_signup_note')}</div>
        <label class="field">${t('coperf_name')}<input class="input" id="a-pname" maxlength="80"></label>
        <div class="row" style="gap:8px;flex-wrap:wrap">
          <label class="field" style="flex:1">${t('coperf_gender')}
            <select class="input" id="a-pgender">
              <option value="">—</option>
              <option value="female">${t('coperf_gender_f')}</option>
              <option value="male">${t('coperf_gender_m')}</option>
            </select></label>
          <label class="field" style="flex:1">${t('coperf_dob')}<input class="input" id="a-pdob" type="date"></label>
        </div>
        <label class="checkbox-row"><input type="checkbox" id="a-p18"><span>${t('coperf_consent')}</span></label>
      </div>` : ''}
      <div class="lang-row">${langPillsHTML()}</div>
      <button class="btn" id="a-go">${t('create_account_btn')}</button>`;
  $('#a-go').onclick = () => doSignup(role);
  paintPromoBanner();
}

async function doAffiliateSignup() {
  const display_name = $('#af-name').value.trim();
  const username = $('#af-user').value.trim();
  const password = $('#af-pass').value;
  const agreed = $('#af-agree').checked;
  if (!display_name || !username || !password) return toast(t('fill_all_fields'));
  if (password.length < 6) return toast(t('err_password_short'));
  if (!agreed) return toast(t('aff_must_agree'));
  const { status, data } = await api('/affiliate/signup', {
    method: 'POST',
    body: JSON.stringify({ username, password, display_name, agreed: true }),
  });
  if (status === 200) return afterLogin(data);
  if (status === 409 && data.error === 'already_have_account') {
    toast(t('aff_already_account'));
    return show('auth', { mode: 'login', role: 'affiliate' });
  }
  const msgs = { username_taken: t('err_username_taken'),
    must_agree: t('aff_must_agree'), missing_fields: t('fill_all_fields') };
  toast(msgs[data.error] || t('err_signup_failed'));
}

/* The role the visitor picked on a "Sign in as a …" button, if any —
 * read from the current auth view params. It only drives the gentle
 * wrong-role note after sign-in; routing never depends on it. */
function pickedLoginRole() {
  const r = S.viewParams && S.viewParams.role;
  return ['fan', 'model', 'affiliate'].includes(r) ? r : null;
}

async function doLogin() {
  const username = $('#a-user').value.trim(), password = $('#a-pass').value;
  if (!username || !password) return toast(t('enter_user_pass'));
  const { status, data } = await api('/auth/login', {
    method: 'POST', body: JSON.stringify({ username, password, guest_token: S.guestToken }),
  });
  if (status === 200) return afterLogin(data, { roleHint: pickedLoginRole() });
  toast(data.error === 'banned' ? t('account_banned') : t('login_failed'));
}

async function doSignup(role) {
  const display_name = $('#a-name').value.trim();
  const username = $('#a-user').value.trim();
  const password = $('#a-pass').value;
  const dob = $('#a-dob').value;
  const agree18 = $('#a-18').checked;
  // Optional contact email (fan form only) — blank = skipped, and the
  // server stores nothing. Sent only when she/he typed one.
  const emailEl = $('#a-email');
  const email = emailEl ? emailEl.value.trim() : '';
  if (!display_name || !username || !password || !dob) return toast(t('fill_all_fields'));
  if (!agree18) return toast(t('must_confirm_18'));
  // Public-display consent (CCBill, Oct 27 2026): a model signup must
  // tick the DISTINCT consent box; the server refuses without it too.
  const publicityConsent = role === 'model' ? !!($('#a-pub') && $('#a-pub').checked) : false;
  if (role === 'model' && !publicityConsent) return toast(t('err_publicity_consent'));
  // Couple signup: the partner block rides along when she filled it
  // in (blank name = skipped; the server never blocks signup over it).
  const pNameEl = $('#a-pname');
  const partner = role === 'model' && pNameEl && pNameEl.value.trim() ? {
    partner_name: pNameEl.value.trim(),
    partner_gender: $('#a-pgender').value,
    partner_dob: $('#a-pdob').value,
    partner_agree18: $('#a-p18').checked,
  } : {};
  // House promo bonus rides along on FAN signup only, when a #promo/
  // code is stashed from this tab session. The server decides whether
  // a grant actually lands (active campaign, pool remaining, first
  // grant for this fan) and reports it back as promo_granted_cents.
  const promoCode = role === 'fan' ? stashedPromoCode() : '';
  const { status, data } = await api('/auth/signup', {
    method: 'POST',
    body: JSON.stringify({ username, password, role, display_name, dob, agree18, guest_token: S.guestToken, language: LANG, ...(role === 'model' ? { section: modelSectionPick, publicity_consent: publicityConsent } : {}), ...partner, ...(email ? { email } : {}), ...(promoCode ? { promo_code: promoCode } : {}) }),
  });
  if (status === 200) {
    const granted = (data && data.promo_granted_cents) || 0;
    if (granted > 0) {
      try { sessionStorage.removeItem('sc_promo_code'); } catch (e) {}
      promoOffer = null;
      setTimeout(() => toast(t('promo_granted', { amount: fmt(granted) })), 800);
    }
    return afterLogin(data);
  }
  const msgs = { username_taken: t('err_username_taken'), must_be_18: t('err_must_be_18'),
    must_declare_section: t('err_must_declare_section'),
    username_is_email: t('err_username_is_email'),
    publicity_consent_required: t('err_publicity_consent'),
    password_too_short: t('err_password_short'), bad_email: t('err_bad_email') };
  toast(msgs[data.error] || t('err_signup_failed'));
}

/* ---------------- Face ID (passkey) sign-in — optional for everyone ---------
 * Hand-rolled WebAuthn client (no dependencies): converts the server's
 * JSON options into PublicKeyCredential options and the credential back
 * into the standard JSON @simplewebauthn/server accepts. The biometric
 * never leaves the device; the server only verifies a signature. */
function pkSupported() {
  return !!(window.PublicKeyCredential && navigator.credentials && window.isSecureContext);
}
function pkB64uToBuf(s) {
  s = String(s).replace(/-/g, '+').replace(/_/g, '/');
  while (s.length % 4) s += '=';
  const bin = atob(s);
  const buf = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
  return buf.buffer;
}
function pkBufToB64u(buf) {
  const bytes = new Uint8Array(buf || new ArrayBuffer(0));
  let bin = '';
  for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
function pkCreateOptions(o) {
  const pk = Object.assign({}, o);
  pk.challenge = pkB64uToBuf(o.challenge);
  pk.user = Object.assign({}, o.user, { id: pkB64uToBuf(o.user.id) });
  if (o.excludeCredentials) {
    pk.excludeCredentials = o.excludeCredentials.map((c) =>
      Object.assign({}, c, { id: pkB64uToBuf(c.id) }));
  }
  return pk;
}
function pkRequestOptions(o) {
  const pk = Object.assign({}, o);
  pk.challenge = pkB64uToBuf(o.challenge);
  if (o.allowCredentials) {
    pk.allowCredentials = o.allowCredentials.map((c) =>
      Object.assign({}, c, { id: pkB64uToBuf(c.id) }));
  }
  return pk;
}
function pkCredJson(cred) {
  const r = cred.response;
  const json = {
    id: cred.id,
    rawId: pkBufToB64u(cred.rawId),
    type: cred.type,
    authenticatorAttachment: cred.authenticatorAttachment || null,
    clientExtensionResults: cred.getClientExtensionResults ? cred.getClientExtensionResults() : {},
    response: { clientDataJSON: pkBufToB64u(r.clientDataJSON) },
  };
  if (r.attestationObject !== undefined) {
    json.response.attestationObject = pkBufToB64u(r.attestationObject);
    if (r.getTransports) { try { json.response.transports = r.getTransports(); } catch (e) {} }
    if (r.getPublicKeyAlgorithm) { try { json.response.publicKeyAlgorithm = r.getPublicKeyAlgorithm(); } catch (e) {} }
    if (r.getAuthenticatorData) { try { json.response.authenticatorData = pkBufToB64u(r.getAuthenticatorData()); } catch (e) {} }
  } else {
    json.response.authenticatorData = pkBufToB64u(r.authenticatorData);
    json.response.signature = pkBufToB64u(r.signature);
    json.response.userHandle = r.userHandle ? pkBufToB64u(r.userHandle) : null;
  }
  return json;
}
function pkDeviceLabel() {
  const ua = navigator.userAgent || '';
  if (/iPhone/.test(ua)) return 'iPhone';
  if (/iPad/.test(ua)) return 'iPad';
  if (/Android/.test(ua)) return 'Android';
  if (/Macintosh/.test(ua)) return 'Mac';
  if (/Windows/.test(ua)) return 'Windows PC';
  return 'This device';
}
function pkErrText(e) {
  if (e && e.name === 'NotAllowedError') return t('pk_err_cancelled');
  if (e && e.name === 'InvalidStateError') return t('pk_err_exists');
  return t('pk_err_generic');
}

/* Runs one WebAuthn ceremony call (create/get) under a watchdog.
 * Field report (Oct 19 2026): in the installed-app context on some
 * phones the ceremony promise NEVER settles — the platform sheet
 * can't present, and the browser neither resolves nor rejects, so
 * the tap looked completely dead: no prompt, no error, nothing.
 * The watchdog aborts the ceremony (AbortController, where the
 * platform supports it) and rejects as NotAllowedError, which the
 * callers already translate into the visible "cancelled — try
 * again, or use your password" message. 60s matches the timeout
 * the server already puts in the ceremony options. */
const PK_CEREMONY_TIMEOUT_MS = 60000;
async function pkCeremony(run) {
  const ctrl = (typeof AbortController !== 'undefined') ? new AbortController() : null;
  let timer = null;
  const watchdog = new Promise((_, reject) => {
    timer = setTimeout(() => {
      if (ctrl) { try { ctrl.abort(); } catch (e) { /* ignore */ } }
      const err = new Error('passkey ceremony timed out');
      err.name = 'NotAllowedError';
      reject(err);
    }, PK_CEREMONY_TIMEOUT_MS);
  });
  try {
    return await Promise.race([run(ctrl ? ctrl.signal : undefined), watchdog]);
  } finally {
    if (timer) clearTimeout(timer);
  }
}

/* Login screen: Face ID sign-in with the username typed in the form. */
async function doPasskeyLogin() {
  const msg = $('#pk-login-msg');
  const say = (txt) => { if (msg) msg.textContent = txt; };
  const userEl = $('#a-user');
  const username = userEl ? userEl.value.trim() : '';
  if (!username) {
    say('Type your username above first, then tap Face ID.');
    if (userEl) userEl.focus();
    return;
  }
  say('');
  try {
    const { status, data } = await api('/auth/passkey/login-options', {
      method: 'POST', body: JSON.stringify({ username }),
    });
    if (status !== 200) {
      say(data.error === 'no_passkey'
        ? 'No Face ID set up for that username yet — sign in with your password first, then turn it on in Settings.'
        : data.error === 'too_many_attempts'
          ? 'Too many tries — wait a minute and try again.'
          : 'Face ID sign-in is not available right now — use your password.');
      return;
    }
    const cred = await pkCeremony((signal) => navigator.credentials.get(
      { publicKey: pkRequestOptions(data), ...(signal ? { signal } : {}) }));
    if (!cred) { say('Face ID was cancelled.'); return; }
    const v = await api('/auth/passkey/login-verify', {
      method: 'POST', body: JSON.stringify({ username, response: pkCredJson(cred) }),
    });
    if (v.status === 200) return afterLogin(v.data, { roleHint: pickedLoginRole() }); // same flow as password login
    say(v.data.error === 'banned' ? 'This account is banned.'
      : "Face ID didn't match — try again, or use your password.");
  } catch (e) {
    say(pkErrText(e));
  }
}

/* Settings card (fan wallet + model settings): enroll / list / remove. */
// Clean feed manager (Settings → My Photo → Clean feed, Oct 23
// 2026): her dedicated CLEAN posts for public surfaces — up to 10
// pictures + 2 videos (the 12-slot shape). Uploads carry the same
// Solo/Co-Star declaration as every profile-media upload
// (pickUploadAppearance) and ride the same endpoint discipline; a
// held item (co-star packet incomplete) shows the same "waiting on
// co-star ID" badge her gallery uses. Deleting removes the post
// everywhere at once (public page, /feed stream, app profile).
/* Deactivate / Hide card (Moderator Role build): she files a
 * request with a mandatory reason; the account stays fully active
 * until the owner approves it in the Manager. One pending request —
 * while one waits, the card shows the pending state instead of the
 * buttons. */
async function loadDeactSettings() {
  const box = $('#deact-box'); if (!box) return;
  let cur = null;
  try {
    const { data } = await api('/model/deactivation-request');
    cur = data && data.request;
  } catch (e) { /* card falls back to the buttons */ }
  if (cur && cur.status === 'pending') {
    box.innerHTML = `<div class="muted small">${t('deact_pending')}</div>`;
    return;
  }
  box.innerHTML = `
    <div class="row" style="gap:8px;flex-wrap:wrap">
      <button class="btn ghost small" id="deact-hide">${t('deact_hide_btn')}</button>
      <button class="btn ghost small" id="deact-off">${t('deact_btn')}</button>
    </div>
    <div id="deact-form" style="display:none;margin-top:10px">
      <textarea class="input" id="deact-reason" rows="3" maxlength="500" placeholder="${t('deact_reason_ph')}" style="width:100%"></textarea>
      <div class="row" style="gap:8px;margin-top:8px">
        <button class="btn small" id="deact-submit">${t('deact_send')}</button>
        <button class="btn ghost small" id="deact-cancel">${t('deact_cancel')}</button>
      </div>
    </div>`;
  let type = null;
  const open = (ty) => { type = ty; $('#deact-form').style.display = 'block'; const ta = $('#deact-reason'); if (ta) ta.focus(); };
  $('#deact-hide').onclick = () => open('hide');
  $('#deact-off').onclick = () => open('deactivate');
  $('#deact-cancel').onclick = () => { $('#deact-form').style.display = 'none'; };
  $('#deact-submit').onclick = async () => {
    const reason = ($('#deact-reason').value || '').trim();
    if (!reason) { toast(t('deact_reason_req')); return; }
    const { status, data } = await api('/model/deactivation-request', { method: 'POST', body: JSON.stringify({ type, reason }) });
    if (status === 200) { toast(t('deact_sent')); loadDeactSettings(); }
    else toast((data && (data.message || data.error)) || 'Error');
  };
}

async function loadCleanFeedSettings() {
  const box = $('#cleanfeed-box');
  if (!box) return;
  const { data } = await api('/model/feed');
  const items = (data && data.items) || [];
  const maxP = (data && data.max_photos) || 10;
  const maxV = (data && data.max_videos) || 2;
  const pics = items.filter((i) => i.kind === 'photo');
  const vids = items.filter((i) => i.kind === 'video');
  const cell = (i) => i.kind === 'video'
    ? `<div class="set-gallery-item"><video src="${esc(i.url)}" style="width:100%;aspect-ratio:1;object-fit:cover;display:block;border-radius:10px;background:#000" muted playsinline loop preload="metadata"></video>${i.held ? `<span class="set-gallery-badge">${t('costar_held_badge')}</span>` : ''}<button class="set-gallery-del" data-feed-del="${i.id}">✕</button></div>`
    : `<div class="set-gallery-item"><img src="${esc(i.url)}" alt="">${i.held ? `<span class="set-gallery-badge">${t('costar_held_badge')}</span>` : ''}<button class="set-gallery-del" data-feed-del="${i.id}">✕</button></div>`;
  box.innerHTML = `
    <div class="muted small" style="margin-bottom:4px">🖼 ${t('feed_count', { n: pics.length, max: maxP })} · 🎬 ${t('feed_count', { n: vids.length, max: maxV })}</div>
    ${items.length ? `<div class="set-gallery-grid">${items.map(cell).join('')}</div>` : `<div class="muted small">${t('feed_empty')}</div>`}
    <div style="margin-top:8px">
      <div class="cf-add-stack">
        ${pics.length < maxP ? `<button class="btn ghost small" id="cf-add-photo">${t('feed_add_photo')}</button>` : ''}
        ${vids.length < maxV ? `<button class="btn ghost small" id="cf-add-video">${t('feed_add_video')}</button>` : ''}
      </div>
      ${(pics.length >= maxP || vids.length >= maxV) ? `<div class="muted small" style="margin-top:6px">${t('feed_full')}</div>` : ''}
    </div>`;
  box.querySelectorAll('[data-feed-del]').forEach((b) => {
    b.onclick = async () => {
      const res = await api(`/model/feed/${b.dataset.feedDel}`, { method: 'DELETE' });
      if (res.status === 200) { toast(t('feed_removed')); loadCleanFeedSettings(); }
      else toast(t('couldnt_save'));
    };
  });
  const addP = box.querySelector('#cf-add-photo');
  if (addP) addP.onclick = () => openPhotoCropper(async (blob) => {
    const decl = await pickUploadAppearance();
    if (!decl) return;
    const fd = new FormData();
    fd.append('photo', blob, 'photo.jpg');
    for (const [k, v] of Object.entries(declFields(decl))) fd.append(k, v);
    const r = await apiUpload('/model/feed/photo', fd);
    if (declRefused(r)) return;
    if (r.status === 200) { toast(t('feed_posted')); loadCleanFeedSettings(); }
    else if (r.data && r.data.error === 'feed_full_photos') toast(t('feed_full'));
    else toast((r.data && r.data.message) || t('couldnt_save'));
  });
  const addV = box.querySelector('#cf-add-video');
  if (addV) addV.onclick = () => {
    const inp = document.createElement('input');
    inp.type = 'file'; inp.accept = 'video/mp4,video/quicktime,video/webm';
    inp.style.cssText = 'position:fixed;left:-9999px;top:0;width:1px;height:1px;opacity:0.01';
    document.body.appendChild(inp);
    inp.onchange = async () => {
      const f = inp.files && inp.files[0];
      inp.remove();
      if (!f) return;
      if (f.size > 15 * 1024 * 1024) { toast('⚠️ That video is too big — 15MB max, keep it short 💋'); return; }
      const decl = await pickUploadAppearance();
      if (!decl) return;
      const fd = new FormData();
      fd.append('video', f);
      for (const [k, v] of Object.entries(declFields(decl))) fd.append(k, v);
      const headers = {};
      if (S.token) headers['Authorization'] = 'Bearer ' + S.token;
      const resp = await fetch('/api/model/feed/video', { method: 'POST', headers, body: fd }).catch(() => null);
      const data = resp ? await resp.json().catch(() => ({})) : {};
      if (declRefused({ status: resp ? resp.status : 0, data })) return;
      if (resp && resp.status === 200) { toast(t('feed_posted')); loadCleanFeedSettings(); }
      else if (data && data.error === 'feed_full_videos') toast(t('feed_full'));
      else toast((data && data.message) || t('couldnt_save'));
    };
    inp.click();
  };
}

async function renderPkSettingsCard() {
  const host = document.getElementById('pk-card');
  if (!host) return;
  const renderUnsupported = () => {
    host.innerHTML = `
      <div class="card">
        <div style="font-weight:800;margin-bottom:6px">${t('pk_h')}</div>
        <div class="muted small">${t('pk_unsupported')}</div>
      </div>`;
  };
  if (!pkSupported()) { renderUnsupported(); return; }
  // pkSupported() only proves the API surface exists. In the
  // installed-app context it can exist while NO platform
  // authenticator is actually usable — the setup button then led
  // nowhere (field report, Oct 19 2026). Ask the platform itself;
  // only a definitive "no" swaps in the unsupported note — a flaky
  // or missing check must never block a working setup.
  let uvpaa = null;
  try {
    if (window.PublicKeyCredential &&
        typeof window.PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable === 'function') {
      uvpaa = await window.PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable();
    }
  } catch (e) { uvpaa = null; }
  if (uvpaa === false) { renderUnsupported(); return; }
  const { data } = await api('/auth/passkey/list').catch(() => ({ data: {} }));
  if (host.isConnected === false) return; // the view moved on mid-load
  const creds = (data && data.credentials) || [];
  host.innerHTML = `
    <div class="card">
      <div style="font-weight:800;margin-bottom:6px">${t('pk_h')}</div>
      <div class="muted small" style="margin-bottom:10px">${t('pk_note')}</div>
      ${creds.map((c) => `
      <div class="row" style="align-items:center;gap:8px;padding:5px 0">
        <span class="small" style="flex:1">📱 ${esc(c.device_label || t('pk_default_name'))} <span class="muted">${t('pk_added', { date: esc(String(c.created_at || '').slice(0, 10)) })}</span></span>
        <button class="btn small ghost" data-pk-del="${c.id}">${t('remove_btn')}</button>
      </div>`).join('')}
      <button class="btn" id="pk-setup" style="width:100%;margin-top:6px">${t('pk_setup')}</button>
      <div class="muted small" id="pk-msg" style="margin-top:6px"></div>
    </div>`;
  const setupBtn = $('#pk-setup');
  if (setupBtn) setupBtn.onclick = async () => {
    const m = $('#pk-msg');
    // Busy state FIRST. Before this fix the tap gave zero feedback
    // for the whole options fetch (up to the 15s api timeout) and
    // for the entire platform ceremony — it read as a dead button
    // (field report, Oct 19 2026).
    const label = setupBtn.textContent;
    setupBtn.disabled = true;
    setupBtn.textContent = t('pk_working');
    if (m) m.textContent = t('pk_working');
    try {
      const { status, data } = await api('/auth/passkey/register-options', { method: 'POST', body: '{}' });
      if (status !== 200) throw new Error(data.error || 'options_failed');
      const cred = await pkCeremony((signal) => navigator.credentials.create(
        { publicKey: pkCreateOptions(data), ...(signal ? { signal } : {}) }));
      if (!cred) { const ce = new Error('cancelled'); ce.name = 'NotAllowedError'; throw ce; }
      const v = await api('/auth/passkey/register-verify', {
        method: 'POST',
        body: JSON.stringify({ response: pkCredJson(cred), label: pkDeviceLabel() }),
      });
      if (v.status !== 200) throw new Error(v.data.error || 'verify_failed');
      if (m) m.textContent = '';
      toast(t('pk_on_toast'));
      renderPkSettingsCard();
    } catch (e) {
      // Silence was the bug: EVERY failure lands in the card AND in
      // a toast (the app's loud channel) — never nowhere.
      const txt = pkErrText(e);
      if (m) m.textContent = txt;
      toast(txt);
    } finally {
      // On success the card re-rendered above, so this button is
      // detached and restoring it is a no-op. On failure it makes
      // the button tappable again under its proper label.
      setupBtn.disabled = false;
      setupBtn.textContent = label;
    }
  };
  host.querySelectorAll('[data-pk-del]').forEach((b) => {
    b.onclick = async () => {
      if (!confirm(t('pk_confirm_remove'))) return;
      const { status } = await api(`/auth/passkey/${b.dataset.pkDel}`, { method: 'DELETE' });
      if (status === 200) { toast(t('pk_removed_toast')); renderPkSettingsCard(); }
      else toast(t('pk_remove_fail'));
    };
  });
}

/* Settings card (fan wallet + model settings): the legal area —
 * one DIRECT row into the Complaints & Content Removal policy
 * (CCBill compliance amendment, Oct 27 2026: the policy must be
 * reachable from every surface where content exists, and the owner
 * wants it one tap from Settings too, not only via Terms). */
function renderLegalSettingsCard() {
  const host = document.getElementById('legal-card');
  if (!host) return;
  host.innerHTML = `
    <div class="card">
      <div style="font-weight:800;margin-bottom:6px">${t('legal_h')}</div>
      <button class="btn ghost" id="set-complaints" style="width:100%">⚖️ ${t('complaints_label')}</button>
    </div>`;
  $('#set-complaints').onclick = () => show('complaints', {});
}

/* Settings card (fan wallet + model settings): change your password.
   The server verifies the current password, enforces the policy and
   revokes every other session; this card mirrors the checks so the
   feedback is instant. */
function renderPwSettingsCard() {
  const host = document.getElementById('pw-card');
  if (!host) return;
  host.innerHTML = `
    <div class="card">
      <div style="font-weight:800;margin-bottom:6px">${t('pw_h')}</div>
      <div class="muted small" style="margin-bottom:10px">${t('pw_note')}</div>
      <label class="field">${t('pw_current')}${pwField('pw-cur', 'current-password')}</label>
      <label class="field">${t('pw_new')}${pwField('pw-new', 'new-password')}</label>
      <label class="field">${t('pw_confirm')}${pwField('pw-confirm', 'new-password')}</label>
      <button class="btn" id="pw-go" style="width:100%;margin-top:6px">${t('pw_go')}</button>
      <div class="muted small" id="pw-msg" style="margin-top:6px"></div>
    </div>`;
  $('#pw-go').onclick = async () => {
    const cur = $('#pw-cur').value, nw = $('#pw-new').value, cf = $('#pw-confirm').value;
    if (!cur || !nw || !cf) return toast(t('pw_fill_all'));
    if (nw !== cf) return toast(t('pw_mismatch'));
    if (nw.length < 10) return toast(t('pw_too_short'));
    if (nw === cur) return toast(t('pw_must_differ'));
    const { status, data } = await api('/me/change-password', {
      method: 'POST', body: JSON.stringify({ current_password: cur, new_password: nw }),
    });
    if (status === 200) {
      $('#pw-cur').value = ''; $('#pw-new').value = ''; $('#pw-confirm').value = '';
      const m = $('#pw-msg'); if (m) m.textContent = t('pw_changed_msg');
      toast(t('pw_changed_toast'));
    } else if (status === 401) {
      toast(t('pw_wrong_current'));
    } else if (data && data.error === 'default_password') {
      toast(t('pw_default'));
    } else if (data && data.error === 'weak_password') {
      toast(t('pw_weak'));
    } else {
      toast(t('pw_fail'));
    }
  };
}

/* Settings card (fan wallet only): OPTIONAL contact email for update
   blasts about favorite models + deals. Owner rule: never forced —
   prefilled from /api/me, Save PATCHes /api/me/contact, Remove clears
   it (empty = NULL server-side = send nothing). Collection only;
   nothing is emailed until an email provider exists. */
function renderContactSettingsCard() {
  const host = document.getElementById('contact-card');
  if (!host) return;
  const current = (S.user && S.user.email) || '';
  host.innerHTML = `
    <div class="card">
      <div style="font-weight:800;margin-bottom:6px">${t('contact_h')}</div>
      <div class="muted small" style="margin-bottom:10px">${t('contact_note')}</div>
      <label class="field">${t('contact_email_label')}<input class="input" id="ct-email" type="email" autocomplete="email" value="${esc(current)}" placeholder="you@example.com"></label>
      <button class="btn" id="ct-save" style="width:100%;margin-top:6px">${t('contact_save')}</button>
      ${current ? '<button class="btn ghost" id="ct-remove" style="width:100%;margin-top:6px">' + t('contact_remove') + '</button>' : ''}
      <div class="muted small" id="ct-msg" style="margin-top:6px"></div>
    </div>`;
  $('#ct-save').onclick = async () => {
    const v = $('#ct-email').value.trim();
    const { status, data } = await api('/me/contact', {
      method: 'PATCH', body: JSON.stringify({ email: v }),
    });
    if (status === 200) {
      if (S.user) S.user.email = data.email || '';
      const m = $('#ct-msg');
      if (data.email) {
        if (m) m.textContent = t('contact_saved_msg', { email: data.email });
        toast(t('contact_saved_toast'));
      } else {
        if (m) m.textContent = t('contact_cleared_msg');
        toast(t('contact_cleared_toast'));
      }
      renderContactSettingsCard();
    } else if (data && data.error === 'bad_email') {
      toast(t('contact_bad_email'));
    } else {
      toast(t('contact_save_fail'));
    }
  };
  const rm = $('#ct-remove');
  if (rm) rm.onclick = async () => {
    const { status } = await api('/me/contact', {
      method: 'PATCH', body: JSON.stringify({ email: '' }),
    });
    if (status === 200) {
      if (S.user) S.user.email = '';
      toast(t('contact_removed_toast'));
      renderContactSettingsCard();
    } else toast(t('contact_remove_fail'));
  };
}

/* Suggestion Box card (fan wallet only, right under the contact
   card): fans drop ideas for things we haven't added yet. POSTs
   /api/suggestions; the server enforces non-empty, ≤1000 chars and
   5-per-24h. Fans only — the host div exists only in the fan wallet,
   and the renderer double-checks the role. */
function renderSuggestionCard() {
  const host = document.getElementById('suggest-card');
  if (!host) return;
  if (!S.user || S.user.role !== 'fan') { host.innerHTML = ''; return; }
  host.innerHTML = `
    <div class="card">
      <div style="font-weight:800;margin-bottom:6px">${t('suggest_title')}</div>
      <div class="muted small" style="margin-bottom:10px">${t('suggest_hint')}</div>
      <label class="field"><textarea class="input" id="sg-text" rows="3" maxlength="1000" placeholder="${t('suggest_placeholder')}"></textarea></label>
      <button class="btn" id="sg-send" style="width:100%;margin-top:6px">${t('suggest_send')}</button>
      <div class="muted small" id="sg-msg" style="margin-top:6px"></div>
    </div>`;
  $('#sg-send').onclick = async () => {
    const v = $('#sg-text').value.trim();
    if (!v) { toast(t('suggest_err_empty')); return; }
    const { status, data } = await api('/suggestions', {
      method: 'POST', body: JSON.stringify({ text: v }),
    });
    if (status === 200) {
      $('#sg-text').value = '';
      const m = $('#sg-msg'); if (m) m.textContent = t('suggest_thanks');
      toast(t('suggest_thanks'));
    } else if (status === 429 || (data && data.error === 'suggest_rate')) {
      toast(t('suggest_err_rate'));
    } else if (data && data.error === 'suggest_too_long') {
      toast(t('suggest_err_long'));
    } else if (data && data.error === 'suggest_empty') {
      toast(t('suggest_err_empty'));
    } else {
      toast((data && data.message) || t('suggest_err_empty'));
    }
  };
}

/* ---------------- MODEL INVITE SIGNUP (?invite=CODE) ---------------- */

async function vInviteSignup(code) {
  // Join warning (Part 2): the warning pops before this door's flow.
  if (!joinWarnAccepted) return joinWarningGate(() => vInviteSignup(code));
  // Section router FIRST (owner pivot, Oct 18 2026): the "Joining as"
  // pick precedes the form; it rides into the register call.
  if (!modelSectionPick) return vSectionGate(() => vInviteSignup(code));
  // Language switches redraw this form (it isn't a show() view).
  entryRerender = () => vInviteSignup(code);
  // Validate the code first
  let valid = false, label = '';
  try {
    const { status, data } = await api(`/invite/${encodeURIComponent(code)}`);
    valid = status === 200 && data.valid;
    label = data.label || '';
  } catch { valid = false; }

  if (!valid) {
    app.innerHTML = `
      <div class="header"><h1>Slut<span class="logo">Camp</span></h1></div>
      <div class="screen"><div class="card" style="text-align:center">
        <div style="font-size:40px">⛔</div>
        <div style="font-weight:800;margin:8px 0">${t('invalid_invite_h')}</div>
        <div class="muted small">${t('invalid_invite_sub')}</div>
        <div class="lang-row">${langPillsHTML()}</div>
        <button class="btn ghost" style="margin-top:12px" onclick="show('landing',{})">${t('back_browsing')}</button>
      </div></div>`;
    return;
  }

  app.innerHTML = `
    <div class="header"><h1>Slut<span class="logo">Camp</span> 💃</h1>
      <div class="sub">${t('invited_model_sub')}${label ? ` · <b>${esc(label)}</b>` : ''}</div></div>
    <div class="screen">
      <div class="card" style="background:linear-gradient(135deg,#3b1d6e,#1a0f2e);text-align:center">
        <div style="font-size:18px;font-weight:800">${t('paid_chat_h')}</div>
        <div class="muted small" style="margin-top:4px">${t('invite_earn_sub')}</div>
      </div>
      <label class="field">${t('stage_name_label')}<input class="input" id="i-name" maxlength="40"></label>
      <label class="field">${t('username')}<input class="input" id="i-user" autocomplete="username"></label>
      <label class="field">${t('password_hint')}${pwField('i-pass', 'new-password')}</label>
      <label class="field">${t('dob')}<input class="input" id="i-dob" type="date"></label>
      <div class="age-box">🔞 <b>${t('age18_only')}</b> ${t('age_id_note')}</div>
      <label class="checkbox-row"><input type="checkbox" id="i-18">
        <span>${t('confirm18')}</span></label>
      ${pubConsentCardHTML('i')}
      <div class="lang-row">${langPillsHTML()}</div>
      <button class="btn" id="i-go">${t('create_model_btn')}</button>
      <button class="btn ghost" id="i-back" style="margin-top:12px">${t('back')}</button>
    </div>`;

  $('#i-back').onclick = () => show('landing', {});
  $('#i-go').onclick = async () => {
    const display_name = $('#i-name').value.trim();
    const username = $('#i-user').value.trim();
    const password = $('#i-pass').value;
    const dob = $('#i-dob').value;
    const agree18 = $('#i-18').checked;
    if (!display_name || !username || !password || !dob) return toast(t('fill_all_fields'));
    if (!agree18) return toast(t('must_confirm_18'));
    const publicityConsent = !!($('#i-pub') && $('#i-pub').checked);
    if (!publicityConsent) return toast(t('err_publicity_consent'));
    const { status, data } = await api('/auth/signup', {
      method: 'POST',
      body: JSON.stringify({ username, password, role: 'model', display_name, dob, agree18, section: modelSectionPick,
        publicity_consent: publicityConsent,
        guest_token: S.guestToken, invite_code: code, language: LANG }),
    });
    if (status === 200) return afterLogin(data);
    const msgs = { username_taken: t('err_username_taken'), must_be_18: t('err_must_be_18'),
      must_declare_section: t('err_must_declare_section'),
      username_is_email: t('err_username_is_email'),
      password_too_short: t('err_password_short'),
      publicity_consent_required: t('err_publicity_consent'),
      bad_invite: t('err_bad_invite'), invite_used: t('err_invite_used') };
    toast(msgs[data.error] || data.message || t('err_signup_failed'));
  };
}

