function affAgreementSections() {
  return AFFILIATE_AGREEMENT_I18N[LANG] || AFFILIATE_AGREEMENT_SECTIONS;
}

/* Affiliate signup via Corry's invite link — agreement popup required */
async function vAffiliateSignup(code) {
  // Join warning (Part 2): the warning pops before this door's flow.
  if (!joinWarnAccepted) return joinWarningGate(() => vAffiliateSignup(code));
  // Language switches redraw this form (it isn't a show() view); the
  // agreement summary renders per-language via affAgreementSections().
  entryRerender = () => vAffiliateSignup(code);
  let valid = false, label = '';
  try {
    const { status, data } = await api(`/affiliate-invite/${encodeURIComponent(code)}`);
    valid = status === 200 && data.valid;
    label = data.label || '';
  } catch { valid = false; }

  if (!valid) {
    app.innerHTML = `
      <div class="header"><h1>Slut<span class="logo">Camp</span></h1></div>
      <div class="screen"><div class="card" style="text-align:center">
        <div style="font-size:40px">⛔</div>
        <div style="font-weight:800;margin:8px 0">${t('aff_invalid_h')}</div>
        <div class="muted small">${t('aff_invalid_sub')}</div>
        <div class="lang-row">${langPillsHTML()}</div>
        <button class="btn ghost" style="margin-top:12px" onclick="show('landing',{})">${t('back_browsing')}</button>
      </div></div>`;
    return;
  }

  const AGREEMENT = affAgreementSections();

  app.innerHTML = `
    <div class="header"><h1>Slut<span class="logo">Camp</span> 🤝</h1>
      <div class="sub">${t('aff_invite_sub')}${label ? ` · ${esc(label)}` : ''}</div></div>
    <div class="screen">
      <div class="card" style="background:linear-gradient(135deg,#3b1d6e,#1a0f2e);text-align:center">
        <div style="font-size:18px;font-weight:800">${t('aff_become_h')}</div>
        <div class="muted small" style="margin-top:4px">${t('aff_become_sub')}</div>
      </div>
      <label class="field">${t('your_name')}<input class="input" id="a-name" maxlength="40"></label>
      <label class="field">${t('username')}<input class="input" id="a-user" autocomplete="username"></label>
      <label class="field">${t('password_hint')}${pwField('a-pass', 'new-password')}</label>
      <div class="card" style="margin-top:12px;max-height:280px;overflow-y:auto;text-align:left">
        <div style="font-weight:800;margin-bottom:8px">${t('aff_agreement_h')}</div>
        ${AGREEMENT.map(([t, b]) => `<div style="margin-bottom:10px"><div style="font-weight:700">${esc(t)}</div><div class="small muted">${esc(b)}</div></div>`).join('')}
      </div>
      <div class="card" style="margin-top:12px;text-align:left"><div class="small">${t('aff_quota_notice')}</div></div>
      <label class="checkbox-row" style="margin-top:12px"><input type="checkbox" id="a-agree">
        <span>${t('aff_agree')}</span></label>
      <div class="lang-row">${langPillsHTML()}</div>
      <button class="btn" id="a-go">${t('aff_accept_btn')}</button>
      <button class="btn ghost" id="a-back" style="margin-top:12px">${t('back')}</button>
    </div>`;

  $('#a-back').onclick = () => show('landing', {});
  $('#a-go').onclick = async () => {
    const display_name = $('#a-name').value.trim();
    const username = $('#a-user').value.trim();
    const password = $('#a-pass').value;
    const agreed = $('#a-agree').checked;
    if (!display_name || !username || !password) return toast(t('fill_all_fields'));
    if (password.length < 6) return toast(t('err_password_short'));
    if (!agreed) return toast(t('aff_must_agree'));
    const { status, data } = await api(`/affiliate-invite/${encodeURIComponent(code)}/signup`, {
      method: 'POST',
      body: JSON.stringify({ username, password, display_name, agreed: true }),
    });
    if (status === 200) return afterLogin(data);
    if (status === 409 && data.error === 'already_have_account') {
      toast(t('aff_already_account'));
      return show('auth', { mode: 'login', role: 'affiliate' });
    }
    const msgs = { username_taken: t('err_username_taken'), bad_invite: t('err_invite_invalid'),
      expired: t('err_invite_expired'), must_agree: t('aff_must_agree'), missing_fields: t('fill_all_fields') };
    toast(msgs[data.error] || t('err_signup_failed'));
  };
}

async function afterLogin(data, opts) {
  S.token = data.token;
  // A storage-blocked WebView must not fail a sign-in the server
  // already accepted: the in-memory token still signs this session
  // in; only the cross-reload persistence is lost.
  try { localStorage.setItem('wc_token', S.token); } catch (e) { /* in-memory token still works */ }
  S.user = data.user;
  wsConnect();
  await refreshMe();
  renderBell();
  subscribePush();
  // One-account tie-in (PR #44 plumbing): she entered via "Sign in
  // as an affiliate" and this ONE account holds the capability —
  // land her on the affiliate side, no wrong-role toast.
  const wantAff = (opts && opts.roleHint) === 'affiliate' && !!S.user.is_affiliate && S.user.role !== 'recruiter';
  if (S.user.role === 'admin') show('managerGate', {});
  else if (wantAff) show('recruiter', {});
  else if (S.user.role === 'model') {
    await checkContractGate();
    show('modelChats', {});
  }
  else if (S.user.role === 'recruiter') show('recruiter', {});
  else show('fanModels', {});
  // Gentle wrong-door note (owner: sign-in must be foolproof): she
  // tapped "Sign in as a model" but the account is really a fan (or
  // the reverse) — she is still signed in and routed by her real
  // role above; the toast just tells her which account this is.
  const wantRole = { fan: 'fan', model: 'model', affiliate: 'recruiter' }[(opts && opts.roleHint) || ''];
  if (wantRole && S.user.role !== wantRole && S.user.role !== 'admin' && !wantAff) {
    const wordKey = { fan: 'role_word_fan', model: 'role_word_model', recruiter: 'role_word_affiliate' }[S.user.role];
    toast(t('signin_wrong_role', { role: t(wordKey) }));
  } else {
    toast(t('welcome_user', { name: S.user.display_name }));
  }
}

/* Contract gate: unsigned models get redirected to sign before doing anything */
async function checkContractGate() {
  if (!S.user || S.user.role !== 'model') return;
  try {
    const { status, data } = await api('/model/contract');
    S.contractSigned = status === 200 && !!data.signed;
    S.contractVersion = status === 200 ? data.version : null;
  } catch (e) { S.contractSigned = true; /* fail open on network error */ }
}

/* One-time congratulations for NEW models — fires after signup/login when
   the account has never been welcomed (users.welcomed_at). Existing models
   were backfilled server-side, so this only greets fresh signups. */
let welcomeShownThisSession = false;
function maybeShowModelWelcome() {
  if (welcomeShownThisSession) return;
  const u = S.user;
  if (!u || u.role !== 'model' || u.welcomed) return;
  if (['liveBroadcast', 'liveWatch'].includes(S.view)) return;
  welcomeShownThisSession = true;
  u.welcomed = true; // optimistic — server stamps it below
  api('/me/welcomed', { method: 'POST', body: JSON.stringify({}) }).catch(() => {});
  let el = document.getElementById('modelWelcome');
  if (!el) {
    el = document.createElement('div');
    el.id = 'modelWelcome';
    el.className = 'model-welcome';
    document.body.appendChild(el);
  }
  el.innerHTML = `
    <div class="mw-card">
      <img class="mw-lips" src="/img/lips-logo.png" alt="">
      <div class="mw-confetti">🎉 💋 🔥</div>
      <div class="mw-title">${t('wm_title', { name: esc(u.display_name) })}</div>
      <div class="mw-welcome">${t('wm_welcome')}</div>
      <p class="mw-body">${t('wm_body')}</p>
      <p class="mw-money">${t('wm_money')}</p>
      <div class="mw-steps-h">${t('wm_steps_h')}</div>
      <div class="mw-steps"><div>${t('wm_step1')}</div><div>${t('wm_step2')}</div><div>${t('wm_step3')}</div></div>
      <button class="btn mw-btn" id="mw-go">${t('wm_btn')}</button>
    </div>`;
  el.hidden = false;
  el.querySelector('#mw-go').onclick = () => { el.hidden = true; };
}

async function refreshMe() {
  const { status, data } = await api('/me');
  if (status === 200) {
    S.user = data.user; S.wallet = data.wallet; S.model = data.model || null;
    // Release door (Oct 22 2026): /api/me flags models with no WOGENT
    // release on file — show() routes them to the one-tap release
    // screen before anything else (see vReleaseGate).
    if (S.user && S.user.role === 'model') S.releaseSigned = !data.user.release_missing;
    syncLangFromUser(data.user);
    maybeShowModelWelcome();
    if (data.commission_pct !== undefined) S.commissionPct = data.commission_pct;
  } else if (status === 401 || status === 403) {
    logout(false);
  }
}

function logout(msg) {
  if (S.token) api('/auth/logout', { method: 'POST' }).catch(() => {});
  S.token = null; S.user = null; S.wallet = null; S.model = null; S.previewFan = false;
  localStorage.removeItem('wc_token');
  if (S.ws) { try { S.ws.close(); } catch (e) {} S.ws = null; }
  show('landing', {});
  if (msg !== false) toast(t('logged_out'));
}

/* ---------------- FAN: models / chats / wallet ---------------- */

/* Model browsing the home screen: tap a sister's tile for her public card
   (status, home rank, rates) — look-only, no fan actions. */
function openModelPeek(m, models) {
  const isMe = !!(S.user && S.user.id === m.id);
  // Her rank line states her TRUE composite position on her own
  // section's ladder (rank_position from the server) — never her index
  // in this payload, which floats the featured model to the top. Top
  // 10 only; a featured model outside the top 10 keeps the pinned
  // note instead. Top-3 positions carry their ladder TITLE here too
  // (owner, Oct 19 2026), e.g. "👸 Queen — #1 in Female".
  const titleSpec = rankTitleSpec(m);
  const rankLine = titleSpec
    ? t('ranked_title_line', {
      title: `${titleSpec.emoji} ${t(titleSpec.key)}`,
      n: m.rank_position,
      section: t(m.section === 'couple' ? 'sf_couples' : 'sf_' + (m.section || 'female')),
    })
    : rankBadgeFor(m)
      ? t('ranked_n', { n: m.rank_position })
      : m.is_featured ? '⭐ Featured — pinned at the top' : '';
  const status = m.is_live
    ? `🔴 LIVE now — ${m.live_viewers || 0} watching`
    : m.is_online ? '🟢 Online now' : '⚫ Offline';
  // Her profile pictures beyond the hero video: her main photo first,
  // then her gallery uploads — up to 10 total, deduped, show what
  // exists (owner spec, Oct 17 2026: 5-10 pictures, NOT a feed). Her
  // clean public photo stays on the Google pages only and never joins
  // this gallery. She also has TWO main videos now: the preview hero
  // above and her second video, rendered in the scroll region below.
  const galleryPics = [...new Set([m.photo_url, ...(Array.isArray(m.gallery_photos) ? m.gallery_photos : [])].filter(Boolean))].slice(0, 10);
  // The official house account is the app itself (owner, Oct 17 2026):
  // its page is look-only for EVERYONE — no Message bar ever, and the
  // Official label stands where the bar would be. It is also never
  // ranked: the server keeps it out of the roster + rank positions.
  const isOfficial = !!m.is_official;
  const officialBarHTML = `<div class="peek-official-bar"><span class="official-pill">${t('official_label')}</span><span class="small muted">${t('official_tagline')}</span></div>`;
  // The sticky Message bar is a FAN action: real fans get it, and the
  // admin's fan-preview stands in for a fan so he sees her page as
  // fans do. Models browsing a sister stay look-only (no fan actions),
  // and nobody ever gets a message-themselves button. The house
  // account rides the fan path (owner comp): it gets the bar too —
  // the server routes its chats fan-side.
  const showMsgBar = !isMe && !!S.user && (S.user.role === 'fan' || S.user.is_house || isFanPreview());
  // Playlist button (owner, Oct 24 2026): a fan on her page adds her
  // to his Playlist right there — the moment he "finds who he likes".
  // True fans only: the follows API is fan-role (the house rides the
  // fan path for chats/lives, never for follows — same rule as the
  // directory hearts, which never render for model-role viewers).
  // Her own page, the official page, guests and previews never see it.
  const showPlaylistBtn = !isMe && !isOfficial && !!S.user && S.user.role === 'fan';
  // A logged-out guest gets a bar in the same pinned spot — never a
  // working chat (guests can't message), but the way forward: join /
  // log in, routed to the auth view. Signed-in users never see this
  // one; fan / model / preview behaviour above is untouched.
  const showGuestBar = !S.user;
  ftSheet(`
    <div class="peek-scroll">
    ${m.preview_video_url ? `
    <div class="peek-hero">
      <video class="peek-hero-video" data-peek-video src="${esc(m.preview_video_url)}" autoplay muted loop playsinline></video>
      <span class="peek-sound-pill" data-peek-sound>🔇 ${t('tap_for_sound')}</span>
    </div>` : ''}
    <div style="text-align:center">
      ${avatarHTML(m.display_name, 'xl', m.photo_url)}
      <div class="sheet-title" style="margin-top:8px">${esc(m.display_name)}${isMe ? ' (that\'s you! 💅)' : ''}${isOfficial ? ` <span class="official-pill">${t('official_label')}</span>` : ''}</div>
      <div class="muted small">@${esc(m.username)}</div>
    </div>
    ${galleryPics.length ? `
    <div class="peek-gallery">
      ${galleryPics.map((p) => `<img class="peek-gallery-img" src="${esc(p)}" alt="${esc(m.display_name)}" loading="lazy">`).join('')}
    </div>` : ''}
    ${m.preview_video_url_2 ? `
    <div class="peek-hero peek-hero-second">
      <video class="peek-hero-video" data-peek-video2 src="${esc(m.preview_video_url_2)}" autoplay muted loop playsinline></video>
      <span class="peek-sound-pill" data-peek-sound2>🔇 ${t('tap_for_sound')}</span>
    </div>` : ''}
    <div class="peek-rows">
      <div class="peek-row"><span>Status</span><b>${status}</b></div>
      <div class="peek-row"><span>❤️ ${t('likes_label')}</span><b>${m.likes_count || 0}</b></div>
      <div class="peek-row"><span>👥 ${t('followers_label')}</span><b data-follow-count="${m.id}">${m.followers_count || 0}</b></div>
      ${rankLine ? `<div class="peek-row"><span>Home rank</span><b>${rankLine}</b></div>` : ''}
      ${isOfficial ? '' : `<div class="peek-row"><span>Messages</span><b>${fmt(m.per_message_cents)} / msg</b></div>`}
      <div class="peek-row"><span>Video calls</span><b>${fmt(m.per_minute_cents)} / min</b></div>
      ${m.schedule_summary ? `<div class="peek-row"><span>Usually live</span><b>${esc(m.schedule_summary)}</b></div>` : ''}
    </div>
    ${showPlaylistBtn ? `<button class="btn playlist-toggle" data-peek-playlist="${m.id}" style="width:100%;margin-top:12px">${t('playlist_add')}</button>` : ''}
    <div id="peek-battles"></div>
    ${m.bio ? `<div class="muted small" style="margin-top:10px">${esc(m.bio)}</div>` : ''}
    <div id="peek-pr"></div>
    <div id="peek-packages"></div>
    <div id="peek-feed"></div>
    ${(m.tags && m.tags.length) ? `<div class="peek-tags">${m.tags.map((tg) => `<button class="disc-chip" data-peek-tag="${esc(tg)}">${esc(tg)}</button>`).join('')}</div>` : ''}
    ${similarModels(m, models).length ? `
    <div style="font-weight:800;margin:14px 0 8px;text-align:left">${t('more_like_her')}</div>
    <div class="sim-rail">
      ${similarModels(m, models).map((s) => `
      <button class="sim-card" data-sim="${s.id}">
        ${avatarHTML(s.display_name, 'sm', s.photo_url)}
        <span class="sim-name">${esc(s.display_name)}</span>
        <span class="small muted">${s.is_live ? '🔴 LIVE' : s.is_online ? '🟢' : '⚫'} ${fmt(s.per_message_cents)}/msg</span>
      </button>`).join('')}
    </div>` : ''}
    <button class="sheet-btn" style="margin-top:12px" onclick="document.getElementById('ft-sheet').remove()">Close</button>
    <p class="muted small" style="text-align:center;margin:14px 0 2px"><a href="javascript:void(0)" data-peek-complaints style="color:var(--pink)">${t('complaints_label')}</a></p>
    </div>
    ${showMsgBar ? `
    <div class="peek-msgbar">
      ${isOfficial
        ? officialBarHTML
        : `<button class="peek-msg-btn" data-peek-msg="${m.id}">${t('msg_her_btn')} · ${t('per_msg_rate', { price: fmt(m.per_message_cents) })}</button>`}
    </div>` : ''}
    ${showGuestBar ? `
    <div class="peek-msgbar">
      ${isOfficial
        ? officialBarHTML
        : `<button class="peek-msg-btn" data-peek-join>${t('msg_her_join_btn')}</button>`}
    </div>` : ''}`);
  const sheet = document.getElementById('ft-sheet');
  if (sheet) {
    // Phase 5: her upcoming private room events (invite window or
    // public leftovers) — tapping one opens the event page.
    const prBox = sheet.querySelector('#peek-pr');
    if (prBox && !isOfficial) {
      api(`/models/${m.id}/private-events`).then(({ data }) => {
        const evs = (data && data.events) || [];
        if (!evs.length) return;
        prBox.innerHTML = `<div style="font-weight:800;margin:14px 0 8px;text-align:left">${t('pr_h')}</div>` +
          evs.map((ev) => `
          <button class="sheet-btn" data-peek-pevent="${ev.id}" style="margin-bottom:8px">🔒 ${esc(ev.title || t('pr_h'))}
            <span class="small muted">· ${prWhenLabel(ev.starts_at)} · ${fmt(ev.seat_price_cents)} · ${t('pr_seats_left', { n: ev.seats_left, total: ev.seats_total })}</span>
          </button>`).join('');
        prBox.querySelectorAll('[data-peek-pevent]').forEach((b) => {
          b.onclick = () => { sheet.remove(); show('privateEvent', { id: parseInt(b.dataset.peekPevent) }); };
        });
      }).catch(() => {});
    }
    // Custom Packages: her pre-made packages + the custom request
    // box (fan-side surface; the loader itself gates fan/house).
    if (!isOfficial) loadPeekPackages(m);
    if (!isOfficial) loadPeekFeed(m);
    // The peek panel becomes a flex column: her page scrolls inside
    // .peek-scroll while the Message bar (fan view) stays pinned to
    // the bottom of the sheet — visible at all times while scrolling.
    const panel = sheet.querySelector('.sheet');
    if (panel) panel.classList.add('peek-sheet');
    const msgBtn = sheet.querySelector('[data-peek-msg]');
    if (msgBtn) {
      msgBtn.onclick = () => {
        if (isFanPreview()) { toast('👁 Preview mode — messaging is fan-only'); return; }
        const id = parseInt(msgBtn.dataset.peekMsg);
        sheet.remove();
        openChatWithModel(id);
      };
    }
    // Playlist button: state loads async (his follows list), the tap
    // rides the same toggleFollow as the directory hearts.
    const plBtn = sheet.querySelector('[data-peek-playlist]');
    if (plBtn) {
      api('/follows').then(({ data }) => {
        const on = ((data && data.following) || []).includes(m.id);
        plBtn.textContent = on ? t('playlist_added') : t('playlist_add');
        plBtn.classList.toggle('in-playlist', on);
      }).catch(() => {});
      plBtn.onclick = () => toggleFollow(m.id, plBtn, m.display_name);
    }
    // Phase 6: her confirmed scheduled showdowns ("⚔️ vs @name — Fri 8 PM")
    // + a fan reminder toggle. Unconfirmed events never render here —
    // the server only returns confirmed ones.
    const pb = sheet.querySelector('#peek-battles');
    if (pb && !isOfficial) {
      api(`/models/${m.id}/battle-events`).then(({ data }) => {
        const events = (data && data.events) || [];
        if (!events.length || !document.getElementById('peek-battles')) return;
        pb.innerHTML = events.map((ev) => {
          const when = new Date(String(ev.starts_at).replace(' ', 'T') + 'Z');
          const label = when.toLocaleDateString(undefined, { weekday: 'short' }) + ' ' +
            when.toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' });
          return `<div class="peek-row"><span>${t('battle_vs_line', { name: '@' + ev.opponent.username })}</span><b>${esc(label)}</b></div>
            ${S.user && S.user.role === 'fan' ? `<button class="btn small ghost" data-battle-remind="${ev.id}" style="width:100%;margin-top:6px">${t('battle_remind')}</button>` : ''}`;
        }).join('');
        pb.querySelectorAll('[data-battle-remind]').forEach((btn) => {
          btn.onclick = async () => {
            const { data } = await api(`/battles/${btn.dataset.battleRemind}/remind`, { method: 'POST' });
            btn.textContent = data && data.reminded ? t('battle_reminded') : t('battle_remind');
          };
        });
      }).catch(() => {});
    }
    // Guest bar: no conversation is started — the tap closes her
    // page and lands on the auth view to join / log in, the same
    // route as the landing's own Log in / Sign up button.
    const joinBtn = sheet.querySelector('[data-peek-join]');
    if (joinBtn) {
      joinBtn.onclick = () => {
        sheet.remove();
        show('auth', {});
      };
    }
    // Complaints & Content Removal at the very foot of her page
    // (owner, Oct 27 2026) — end of the scroll content, under the
    // Close row, above the pinned Message bar. Same policy page as
    // the Terms / Settings rows; the sheet closes first, like every
    // other peek navigation.
    const cpLink = sheet.querySelector('[data-peek-complaints]');
    if (cpLink) {
      cpLink.onclick = () => {
        sheet.remove();
        show('complaints', {});
      };
    }
    // Preview video hero: tap toggles the sound. Unmuting restarts from
    // 0 so her spoken hook is heard from the top; tapping again re-mutes.
    // The pill mirrors the state (🔇 tap for sound / 🔊 tap to mute).
    const pv = sheet.querySelector('[data-peek-video]');
    if (pv) {
      const pill = sheet.querySelector('[data-peek-sound]');
      const togglePeekSound = () => {
        if (pv.muted) {
          pv.muted = false;
          try { pv.currentTime = 0; } catch (e) { /* not seekable yet */ }
          const p = pv.play(); if (p && p.catch) p.catch(() => {});
        } else {
          pv.muted = true;
        }
        if (pill) pill.innerHTML = pv.muted ? `🔇 ${t('tap_for_sound')}` : `🔊 ${t('tap_to_mute')}`;
      };
      pv.onclick = togglePeekSound;
      if (pill) pill.onclick = togglePeekSound;
    }
    // Second profile video: same treatment as the hero — tap toggles
    // the sound, unmuting restarts from 0 so her intro is heard from
    // the top; its pill mirrors the state.
    const pv2 = sheet.querySelector('[data-peek-video2]');
    if (pv2) {
      const pill2 = sheet.querySelector('[data-peek-sound2]');
      const togglePeekSound2 = () => {
        if (pv2.muted) {
          pv2.muted = false;
          try { pv2.currentTime = 0; } catch (e) { /* not seekable yet */ }
          const p = pv2.play(); if (p && p.catch) p.catch(() => {});
        } else {
          pv2.muted = true;
        }
        if (pill2) pill2.innerHTML = pv2.muted ? `🔇 ${t('tap_for_sound')}` : `🔊 ${t('tap_to_mute')}`;
      };
      pv2.onclick = togglePeekSound2;
      if (pill2) pill2.onclick = togglePeekSound2;
    }
    sheet.querySelectorAll('[data-sim]').forEach((b) => {
      b.onclick = () => {
        const s = (models || []).find((x) => x.id === parseInt(b.dataset.sim));
        if (s) openModelPeek(s, models);
      };
    });
    // Tapping one of her tags jumps to the directory filtered by it.
    sheet.querySelectorAll('[data-peek-tag]').forEach((b) => {
      b.onclick = () => {
        disc.tag = b.dataset.peekTag;
        homePage = 1;
        sheet.remove();
        show(S.user ? 'fanModels' : 'landing', {});
      };
    });
  }
}

async function vFanModels() {
  const { data } = await api('/models');
  const models = data.models || [];
  const official = data.official || null;
  const { data: schedData } = await api('/live/schedule');
  const house = (schedData && schedData.house) || null;
  await refreshMe();
  const inPreview = isFanPreview();
  const isModelViewer = !!(S.user && (S.user.role === 'model' || inPreview));
  // Owner comp: the house account is model-role but routes like a
  // fan wherever a tap is routed by role (live tiles, official card).
  const isHouseViewer = !!(S.user && S.user.is_house);
  let following = [];
  if (!isModelViewer) {
    try { const f = await api('/follows'); following = f.data.following || []; } catch (e) {}
  }
  const isFanUser = !!(S.user && S.user.role === 'fan');
  const shown = applyDiscovery(models, disc);
  const heartFor = isModelViewer ? null : (m) => `
            <span class="follow-btn tile-heart ${following.includes(m.id) ? 'following' : ''}" data-follow="${m.id}" title="${t('follow_title')}">${following.includes(m.id) ? '❤️' : '🤍'}</span>`;
  app.innerHTML = `
    <div class="header"><div class="home-head-row"><h1>Slut<span class="logo">Camp</span></h1>
      ${isFanUser ? `<button class="btn small ghost home-logout-btn" id="home-logout">${t('log_out')}</button>` : ''}</div>
      <div>${inPreview
        ? '<span class="balance-pill">👁 Previewing as fan</span>'
        : isModelViewer
        ? '<span class="balance-pill">👀 Browsing the home screen</span>'
        : `<span class="balance-pill">💰 ${fmt(S.wallet ? S.wallet.credits_cents : 0)}</span>`}</div></div>
    <div class="screen">
      ${sectionTabsHTML()}
      ${isModelViewer ? '' : houseBannerHTML(house)}
      ${sideSwitchHTML('main')}
      ${officialCardHTML(official)}
      ${athCardHTML()}
      ${livesBtnHTML(models)}
      ${discoveryBarHTML(models)}
      ${newModelsRailHTML(models, heartFor)}
      ${!models.length
        ? `<div class="empty"><div class="big">😴</div>${t('no_models')}</div>`
        : shown.length ? homeTilesHTML(shown, heartFor, { crown: !discActive(disc), rankBadges: !discActive(disc) })
        : `<div class="empty"><div class="big">🔍</div>${t('no_matches')}</div>`}
      <p class="muted small" style="text-align:center;margin:18px 0 6px"><a href="javascript:void(0)" id="home-complaints" style="color:var(--pink)">${t('complaints_label')}</a></p>
    </div>`;
  wireAthCard();
  wireHouseBanner();
  wireDiscovery('fanModels');
  // The section strip is wired for EVERY home viewer, models included
  // (owner ruling, Oct 19 2026: "I don't see sections" — a model's
  // home is a front page too, lands on Female, and her tab taps
  // re-filter her grid + New Models rail in place, same as a fan's).
  wireSectionTabs(() => show('fanModels', {}));
  // Pinned official card: LIVE → join the stream exactly like a live
  // model tile; quiet → its look-only profile page. Model viewers and
  // the admin fan-preview stay look-only in both states (the grid rule);
  // the house account takes the fan path here too (owner comp).
  wireSideSwitch();
  app.querySelectorAll('[data-official]').forEach((b) => {
    b.onclick = () => {
      if (!official) return;
      if (official.is_live && official.live_session_id && (!isModelViewer || isHouseViewer)) {
        return watchLive(parseInt(official.live_session_id));
      }
      openModelPeek(official, models);
    };
  });
  const lv = $('#go-lives');
  if (lv) lv.onclick = () => show('lives', {});
  const hlo = $('#home-logout');
  if (hlo) hlo.onclick = () => { if (confirm('Log out of SlutCamp?')) logout(); };
  // Complaints & Content Removal at the foot of the front page
  // (owner, Oct 27 2026) — below the tile grid + pagination, opens
  // the same policy page as the Terms / Settings rows.
  const hcp = $('#home-complaints');
  if (hcp) hcp.onclick = () => show('complaints', {});
  app.querySelectorAll('[data-model]').forEach((b) => {
    b.onclick = () => {
      if (isModelViewer && !isHouseViewer) {
        const m = models.find((x) => x.id === parseInt(b.dataset.model));
        if (m) openModelPeek(m, models);
        return;
      }
      const liveId = b.dataset.live;
      if (liveId) return watchLive(parseInt(liveId));
      // Fans land on her profile first (owner, Oct 17 2026): her
      // pictures + preview video, with the Message bar pinned while
      // they scroll — the bar opens the chat from there.
      if (S.user && (S.user.role === 'fan' || S.user.is_house)) {
        const m = models.find((x) => x.id === parseInt(b.dataset.model));
        if (m) { openModelPeek(m, models); return; }
      }
      openChatWithModel(parseInt(b.dataset.model));
    };
  });
  app.querySelectorAll('[data-follow]').forEach((f) => {
    f.onclick = (e) => {
      e.stopPropagation();
      const fm = models.find((x) => x.id === parseInt(f.dataset.follow));
      toggleFollow(parseInt(f.dataset.follow), f, fm ? fm.display_name : '');
    };
  });
}

/* ---------------- FAN: My Playlist (the follows engine, rebranded) ----------------
   One fan, one Playlist (owner, Oct 24 2026): the models he added,
   LIVE first — the "she's live" surface for his own girls — then by
   her true section-rank position. Ordering is pure + unit-tested. */
function playlistOrder(models, followingIds) {
  const rankOf = (m) => (Number.isInteger(m.rank_position) ? m.rank_position : Number.MAX_SAFE_INTEGER);
  return (models || [])
    .filter((m) => (followingIds || []).includes(m.id))
    .sort((a, b) => (Number(!!b.is_live) - Number(!!a.is_live))
      || ((b.live_viewers || 0) - (a.live_viewers || 0))
      || (rankOf(a) - rankOf(b)));
}

function playlistCardHTML(m) {
  const status = m.is_live
    ? `🔴 LIVE now — ${m.live_viewers || 0} watching`
    : m.is_online ? '🟢 Online now' : '⚫ Offline';
  return `
    <div class="list-item playlist-card" data-pl-open="${m.id}">
      <span class="avatar-wrap">${avatarHTML(m.display_name, '', m.photo_url)}${m.is_live ? '<span class="online-dot"></span>' : ''}</span>
      <span class="grow">
        <span class="title">${esc(m.display_name)}${m.is_live ? ' <span class="live-badge">🔴 LIVE</span>' : ''}</span><br>
        <span class="preview">${status}</span><br>
        <span class="small muted">${t('per_msg_rate', { price: fmt(m.per_message_cents) })}</span>
      </span>
      <span class="row" style="gap:6px">
        <button class="btn small" data-pl-msg="${m.id}">${t('msg_her_btn')}</button>
        <button class="btn small ghost" data-pl-remove="${m.id}">${t('remove_btn')}</button>
      </span>
    </div>`;
}

async function vPlaylist() {
  await refreshMe();
  const { data } = await api('/models');
  const models = data.models || [];
  let following = [];
  try { const f = await api('/follows'); following = f.data.following || []; } catch (e) {}
  const mine = playlistOrder(models, following);
  app.innerHTML = `
    <div class="header"><h1>${t('playlist_title')}</h1>
      <div><span class="balance-pill">💰 ${fmt(S.wallet ? S.wallet.credits_cents : 0)}</span></div></div>
    <div class="screen">
      ${mine.length ? mine.map((m) => playlistCardHTML(m)).join('')
        : `<div class="empty"><div class="big">🎵</div>${t('playlist_empty')}</div>`}
    </div>`;
  // Card tap: a live girl goes straight to her stream (the directory
  // rule); otherwise her profile page opens.
  app.querySelectorAll('[data-pl-open]').forEach((card) => {
    card.onclick = () => {
      const m = models.find((x) => x.id === parseInt(card.dataset.plOpen));
      if (!m) return;
      if (m.is_live && m.live_session_id) return watchLive(parseInt(m.live_session_id));
      openModelPeek(m, models);
    };
  });
  app.querySelectorAll('[data-pl-msg]').forEach((b) => {
    b.onclick = (e) => { e.stopPropagation(); openChatWithModel(parseInt(b.dataset.plMsg)); };
  });
  app.querySelectorAll('[data-pl-remove]').forEach((b) => {
    b.onclick = async (e) => {
      e.stopPropagation();
      const m = models.find((x) => x.id === parseInt(b.dataset.plRemove));
      await toggleFollow(parseInt(b.dataset.plRemove), null, m ? m.display_name : '');
      show('playlist', {});
    };
  });
}

async function vFanChats() { return vChatList('fan'); }
async function vModelChats() { return vChatList('model'); }

/* ---------------- FAN: group live streams listing ---------------- */

async function vFanLive() {
  await refreshMe();
  const inPreview = isFanPreview();
  const { data } = await api('/live');
  const streams = data.live || [];
  // Preview: stream rows open the model's peek card instead of joining.
  let previewModels = [];
  if (inPreview) {
    try { const md = await api('/models'); previewModels = md.data.models || []; } catch (e) {}
  }
  const { data: schedData } = await api('/live/schedule');
  const upcoming = (schedData.upcoming || []).slice(0, 10);
  const house = (schedData && schedData.house) || null;
  app.innerHTML = `
    <div class="header"><h1>${t('fanlive_h')}</h1>
      <div>${inPreview
        ? '<span class="balance-pill">👁 Previewing as fan</span>'
        : `<span class="balance-pill">💰 ${fmt(S.wallet ? S.wallet.credits_cents : 0)}</span>`}</div></div>
    <div class="screen">
      ${inPreview ? '' : houseBannerHTML(house)}
      ${streams.map((s) => `
        <button class="list-item" data-stream="${s.session_id}" data-model="${s.model_id}" data-battle="${s.battle_id || ''}" style="background:var(--card);border-radius:14px;margin-bottom:10px;border:1px solid rgba(239,68,68,.35)">
          <span class="avatar-wrap">${avatarHTML(s.model_name, '', s.model_photo_url)}<span class="online-dot"></span></span>
          <span class="grow">
            <span class="title">${esc(s.model_name)} <span class="live-badge">🔴 LIVE</span>${s.battle_id ? ` <span class="live-badge" style="background:linear-gradient(135deg,#f59e0b,#ef4444)">${t('battle_in_battle')}</span>` : ''}${s.battle_looking ? ` <span class="live-badge" style="background:#7c3aed">${t('battle_looking')}</span>` : ''}</span><br>
            ${s.title ? `<span class="preview" style="font-weight:700;color:#fff">${esc(s.title)}</span><br>` : ''}
            <span class="small muted">${t('watching_gifts', { v: s.viewers, g: fmt(s.gift_cents || 0) })}</span><br>
            <span class="small" style="color:#f87171;font-weight:800">${t('join_free_line')}</span>
          </span><span style="font-size:22px">›</span>
        </button>`).join('') || `
        <div class="empty"><div class="big">📺</div>${t('noone_live')}<br>
          <span class="small">${t('check_back')}</span></div>`}
      ${upcoming.length ? `
      <div style="font-weight:800;margin:18px 0 10px">${t('coming_up')}</div>
      ${upcoming.map((u) => `
        <div class="list-item" style="background:var(--card);border-radius:14px;margin-bottom:10px;border:1px solid rgba(139,92,246,.18);cursor:default">
          <span class="avatar-wrap">${avatarHTML(u.model_name, '', u.photo_url)}</span>
          <span class="grow">
            <span class="title">${esc(u.model_name)}</span><br>
            ${u.title ? `<span class="small" style="color:#fff;font-weight:700">${esc(u.title)}</span><br>` : ''}
            <span class="small muted">📅 ${u.day_label} ${u.time_label}</span><br>
            <span class="small" style="color:var(--gold);font-weight:700">⏱ ${bookingCountdown(u.starts_at)}</span>
          </span>
        </div>`).join('')}` : ''}
    </div>`;
  if (!inPreview) wireHouseBanner();
  app.querySelectorAll('[data-stream]').forEach((b) => {
    b.onclick = () => {
      if (inPreview) {
        const m = previewModels.find((x) => x.id === parseInt(b.dataset.model));
        if (m) openModelPeek(m, previewModels);
        else toast('👁 Preview mode — joining a live is fan-only');
        return;
      }
      // A battling model's row opens the battle stage, not her solo stream.
      if (b.dataset.battle) return openBattleStage(parseInt(b.dataset.battle));
      watchLive(parseInt(b.dataset.stream));
    };
  });
}

